-- ===========================================================================
-- 0005_users_rbac.sql
-- ===========================================================================
-- SSB Academy — Phase 1 (T080), step 2 of 2: central users + RBAC.
-- Run once in the Supabase SQL Editor, AFTER 0004_super_admin_role.sql.
--
-- Design notes
--  * Supabase Auth (auth.users) stays the ONLY authentication system.
--    public.profiles is the central users table: one row per account with
--    role, academy membership, contact details, account status and last login.
--  * Role-specific data lives in student_profiles / mentor_profiles /
--    academy_admin_profiles / super_admin_profiles (1:1 with profiles).
--  * Privileged columns (role, academy_id, status, email, last_login_at) can't
--    be changed by the account holder. Before this migration,
--    "profiles_update_own" let any user rewrite their own role. A trigger now
--    rejects that for everyone except an active super admin and trusted
--    server contexts (service role / SQL Editor / auth triggers).
--  * Signup no longer trusts a role sent by the browser: self-signup can only
--    create a student or an academy admin. A mentor account (with an academy)
--    only comes from a real invite (auth.users.invited_at is set by
--    inviteUserByEmail). Any role at all only comes from app_metadata, which
--    only the service role can write. super_admin is never self-assigned.
--  * The first super admin is bootstrapped by hand, once:
--
--      update public.profiles set role = 'super_admin'
--      where email = 'you@example.com';
--
--  * Sensitive super-admin actions are written to public.audit_log.

-- ---------------------------------------------------------------------------
-- 1. Central users table: profiles gains identity/status columns
-- ---------------------------------------------------------------------------

create type public.user_status as enum ('active', 'suspended');

alter table public.profiles
  add column email text,
  add column phone text,
  add column status public.user_status not null default 'active',
  add column last_login_at timestamptz,
  add column updated_at timestamptz not null default now();

update public.profiles p
set email = u.email, last_login_at = u.last_sign_in_at
from auth.users u
where u.id = p.id;

create unique index profiles_email_unique on public.profiles (lower(email)) where email is not null;
create index profiles_role_idx on public.profiles (role);
create index profiles_status_idx on public.profiles (status);
create index profiles_academy_idx on public.profiles (academy_id);

-- ---------------------------------------------------------------------------
-- 2. Role helpers (SECURITY DEFINER: usable inside RLS without recursion)
-- ---------------------------------------------------------------------------

create function public.is_super_admin()
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'super_admin' and status = 'active'
  )
$$;

create function public.current_user_role()
returns public.user_role
language sql
stable
security definer set search_path = public
as $$
  select role from public.profiles where id = auth.uid()
$$;

-- ---------------------------------------------------------------------------
-- 3. Role-specific profile tables (1:1 with profiles)
-- ---------------------------------------------------------------------------

create table public.student_profiles (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  target_exam text,
  preparation_stage text,
  goals text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.mentor_profiles (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  bio text,
  expertise text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.academy_admin_profiles (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  job_title text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.super_admin_profiles (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.student_profiles enable row level security;
alter table public.mentor_profiles enable row level security;
alter table public.academy_admin_profiles enable row level security;
alter table public.super_admin_profiles enable row level security;

create policy "student_profiles_own" on public.student_profiles
  for select using (user_id = auth.uid() or public.is_super_admin());
create policy "student_profiles_update_own" on public.student_profiles
  for update using (user_id = auth.uid());
create policy "mentor_profiles_own" on public.mentor_profiles
  for select using (user_id = auth.uid() or public.is_super_admin());
create policy "mentor_profiles_update_own" on public.mentor_profiles
  for update using (user_id = auth.uid());
create policy "academy_admin_profiles_own" on public.academy_admin_profiles
  for select using (user_id = auth.uid() or public.is_super_admin());
create policy "academy_admin_profiles_update_own" on public.academy_admin_profiles
  for update using (user_id = auth.uid());
create policy "super_admin_profiles_own" on public.super_admin_profiles
  for select using (user_id = auth.uid() or public.is_super_admin());
create policy "super_admin_profiles_update_own" on public.super_admin_profiles
  for update using (user_id = auth.uid());

-- Creates the role-profile row for a user's current role (idempotent).
create function public.ensure_role_profile(p_user uuid, p_role public.user_role)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  case p_role
    when 'student' then insert into public.student_profiles (user_id) values (p_user) on conflict do nothing;
    when 'mentor' then insert into public.mentor_profiles (user_id) values (p_user) on conflict do nothing;
    when 'academy_admin' then insert into public.academy_admin_profiles (user_id) values (p_user) on conflict do nothing;
    when 'super_admin' then insert into public.super_admin_profiles (user_id) values (p_user) on conflict do nothing;
  end case;
end;
$$;

revoke execute on function public.ensure_role_profile(uuid, public.user_role) from public, anon, authenticated;

select public.ensure_role_profile(id, role) from public.profiles;

-- ---------------------------------------------------------------------------
-- 4. Hardened signup trigger (replaces the 0001 version)
-- ---------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  app_role text := new.raw_app_meta_data->>'role';        -- service-role only
  meta_role text := new.raw_user_meta_data->>'role';      -- browser-controlled
  signup_role public.user_role;
  new_academy_id uuid;
  trusted_academy text;
begin
  if app_role in ('student', 'mentor', 'academy_admin', 'super_admin') then
    signup_role := app_role::public.user_role;
    trusted_academy := new.raw_app_meta_data->>'academy_id';
  elsif meta_role = 'mentor' and new.invited_at is not null then
    -- inviteUserByEmail (server-side, service role) is the only way to get here.
    signup_role := 'mentor';
    trusted_academy := new.raw_user_meta_data->>'academy_id';
  elsif meta_role = 'academy_admin' then
    signup_role := 'academy_admin';
  else
    signup_role := 'student';
  end if;

  if signup_role = 'academy_admin' then
    insert into public.academies (name, owner_id)
    values (coalesce(nullif(btrim(new.raw_user_meta_data->>'academy_name'), ''), 'My Academy'), new.id)
    returning id into new_academy_id;
  elsif trusted_academy is not null then
    new_academy_id := trusted_academy::uuid;
  end if;

  insert into public.profiles (id, role, full_name, academy_id, email, last_login_at)
  values (
    new.id,
    signup_role,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    new_academy_id,
    new.email,
    new.last_sign_in_at
  );

  perform public.ensure_role_profile(new.id, signup_role);
  return new;
end;
$$;

-- Keep profiles.email / last_login_at in step with Supabase Auth (the source).
create function public.sync_auth_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  update public.profiles
  set email = new.email, last_login_at = new.last_sign_in_at
  where id = new.id;
  return new;
end;
$$;

create trigger on_auth_user_updated
  after update of email, last_sign_in_at on auth.users
  for each row execute function public.sync_auth_user();

-- ---------------------------------------------------------------------------
-- 5. Privileged-column guard + super-admin access
-- ---------------------------------------------------------------------------

create function public.guard_profile_update()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  privileged_changed boolean :=
    new.role is distinct from old.role
    or new.academy_id is distinct from old.academy_id
    or new.status is distinct from old.status
    or new.email is distinct from old.email
    or new.last_login_at is distinct from old.last_login_at
    or new.id is distinct from old.id;
begin
  -- auth.uid() is null for trusted contexts: service role, SQL Editor, and the
  -- auth-schema triggers above. Only API callers are checked.
  if auth.uid() is not null and privileged_changed then
    if not public.is_super_admin() then
      raise exception 'only a super admin can change role, academy, status or email'
        using errcode = '42501';
    end if;
    if old.id = auth.uid() and (new.role is distinct from old.role or new.status is distinct from old.status) then
      raise exception 'you cannot change your own role or status'
        using errcode = '42501';
    end if;
  end if;

  new.updated_at := now();
  if new.role is distinct from old.role then
    perform public.ensure_role_profile(new.id, new.role);
  end if;
  return new;
end;
$$;

create trigger profiles_guard_update
  before update on public.profiles
  for each row execute function public.guard_profile_update();

create policy "profiles_select_super_admin" on public.profiles
  for select using (public.is_super_admin());

create policy "profiles_update_super_admin" on public.profiles
  for update using (public.is_super_admin()) with check (public.is_super_admin());

create policy "academies_select_super_admin" on public.academies
  for select using (public.is_super_admin());

-- ---------------------------------------------------------------------------
-- 6. Audit log for sensitive administrative actions (AGENTS.md §16)
-- ---------------------------------------------------------------------------

create table public.audit_log (
  id bigint generated always as identity primary key,
  actor_id uuid references public.profiles(id) on delete set null,
  action text not null,
  target_type text not null,
  target_id uuid,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index audit_log_target_idx on public.audit_log (target_type, target_id, created_at desc);
create index audit_log_created_idx on public.audit_log (created_at desc);

alter table public.audit_log enable row level security;

-- Append-only: super admins insert entries as themselves and read them all.
-- No update/delete policy exists, so entries can't be edited or removed.
create policy "audit_log_insert_super_admin" on public.audit_log
  for insert with check (public.is_super_admin() and actor_id = auth.uid());

create policy "audit_log_select_super_admin" on public.audit_log
  for select using (public.is_super_admin());

-- ===========================================================================
-- 0006_academies.sql
-- ===========================================================================
-- SSB Academy — Phase 2 (T081): academies as a managed domain.
-- Run once in the Supabase SQL Editor, AFTER 0004 and 0005.
--
-- Design notes
--  * academies gains profile fields (description, logo URL, contact) and a
--    status. Membership stays in ONE place: profiles.academy_id.
--  * Only a super admin can create academies, change an academy's status or
--    owner. Academy admins can edit their own academy's name, description and
--    contact details (enforced by RLS + a column guard trigger).
--  * academy_member_counts is a security-invoker view: each caller sees counts
--    only over the profiles their own RLS lets them read.

create type public.academy_status as enum ('active', 'suspended');

alter table public.academies
  add column description text,
  add column logo_url text,
  add column contact_email text,
  add column contact_phone text,
  add column status public.academy_status not null default 'active',
  add column updated_at timestamptz not null default now();

-- NOT VALID: enforced for new/updated rows without failing on legacy names.
alter table public.academies
  add constraint academies_name_length check (char_length(btrim(name)) between 2 and 80) not valid;

create index academies_status_idx on public.academies (status);
create index academies_created_idx on public.academies (created_at desc);

-- The academy the signed-in academy admin belongs to (defined in 0003) is the
-- scope for admin edits, whether or not they are the original owner.
create policy "academies_update_academy_admin" on public.academies
  for update
  using (id = public.current_admin_academy_id())
  with check (id = public.current_admin_academy_id());

create policy "academies_insert_super_admin" on public.academies
  for insert with check (public.is_super_admin());

create policy "academies_update_super_admin" on public.academies
  for update using (public.is_super_admin()) with check (public.is_super_admin());

create function public.guard_academy_update()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  if auth.uid() is not null and not public.is_super_admin()
     and (new.status is distinct from old.status
          or new.owner_id is distinct from old.owner_id
          or new.id is distinct from old.id) then
    raise exception 'only a super admin can change an academy''s status or owner'
      using errcode = '42501';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger academies_guard_update
  before update on public.academies
  for each row execute function public.guard_academy_update();

create view public.academy_member_counts
with (security_invoker = true) as
  select
    academy_id,
    count(*) filter (where role = 'academy_admin') as admins,
    count(*) filter (where role = 'mentor') as mentors,
    count(*) filter (where role = 'student') as students
  from public.profiles
  where academy_id is not null
  group by academy_id;

grant select on public.academy_member_counts to authenticated;

-- ===========================================================================
-- 0007_batch_membership.sql
-- ===========================================================================
-- SSB Academy — Phase 3 (T082): batch membership (students + mentors).
-- Run once in the Supabase SQL Editor, AFTER 0004–0006.
--
-- Design notes
--  * batch_students: a student is in at most ONE batch (unique student_id).
--  * batch_mentors: any number of mentors per batch. Replaces the single
--    batches.mentor_id column (existing assignments are copied, then the
--    column is dropped), so membership has exactly one source of truth.
--  * A trigger enforces that the person has the right role and belongs to the
--    batch's academy — RLS alone can't express that cross-row rule.
--  * Mentors read only their own batches, those batches' students and their
--    co-mentors (AGENTS.md §10: never an unrelated batch or academy).
--  * Academy admins add/remove academy students through SECURITY DEFINER
--    functions, because profiles.academy_id is otherwise super-admin-only
--    (0005). The functions only ever touch the caller's own academy.

-- ---------------------------------------------------------------------------
-- 0. Legacy academy_students TABLE (added 2026-10-18)
-- ---------------------------------------------------------------------------
-- Some databases (production included) ran a superseded branch migration
-- (commit 6b2ee12, "0004_academy_students") that created a name-only
-- academy_students TABLE. Section 5 below creates a VIEW with that name, so the
-- table is renamed out of the way — every row, constraint, policy and trigger
-- is kept — and taken off the API. A no-op on databases that never had it.
do $$
begin
  if (select relkind from pg_class where oid = to_regclass('public.academy_students')) = 'r' then
    if to_regclass('public.academy_students_legacy') is not null then
      raise exception 'public.academy_students_legacy already exists; resolve it before running 0007.';
    end if;
    alter table public.academy_students rename to academy_students_legacy;
    revoke all on table public.academy_students_legacy from anon, authenticated;
    raise notice '0007: legacy table public.academy_students renamed to academy_students_legacy (data kept).';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------

create table public.batch_students (
  batch_id uuid not null references public.batches(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  added_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (batch_id, student_id),
  constraint batch_students_one_batch unique (student_id)
);

create table public.batch_mentors (
  batch_id uuid not null references public.batches(id) on delete cascade,
  mentor_id uuid not null references public.profiles(id) on delete cascade,
  assigned_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (batch_id, mentor_id)
);

create index batch_mentors_mentor_idx on public.batch_mentors (mentor_id);

alter table public.batch_students enable row level security;
alter table public.batch_mentors enable row level security;

-- Copy existing single-mentor assignments, then retire the column (and the
-- 0003 policies that reference it).
insert into public.batch_mentors (batch_id, mentor_id)
select id, mentor_id from public.batches where mentor_id is not null
on conflict do nothing;

drop policy "batches_insert_admin" on public.batches;
drop policy "batches_update_admin" on public.batches;
drop index if exists public.batches_mentor_idx;
alter table public.batches drop column mentor_id;

create policy "batches_insert_admin" on public.batches
  for insert with check (academy_id = public.current_admin_academy_id());

create policy "batches_update_admin" on public.batches
  for update
  using (academy_id = public.current_admin_academy_id())
  with check (academy_id = public.current_admin_academy_id());

-- ---------------------------------------------------------------------------
-- 2. Integrity: right role, same academy
-- ---------------------------------------------------------------------------

create function public.check_batch_member()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  batch_academy uuid;
  member_id uuid;
  member_role public.user_role;
  member_academy uuid;
  wanted public.user_role;
begin
  select academy_id into batch_academy from public.batches where id = new.batch_id;
  if tg_table_name = 'batch_students' then
    member_id := new.student_id; wanted := 'student';
  else
    member_id := new.mentor_id; wanted := 'mentor';
  end if;
  select role, academy_id into member_role, member_academy from public.profiles where id = member_id;

  if member_role is distinct from wanted then
    raise exception 'only a % can be added here', wanted using errcode = '23514';
  end if;
  if member_academy is null or member_academy is distinct from batch_academy then
    raise exception 'that person is not in this batch''s academy' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger batch_students_check before insert or update on public.batch_students
  for each row execute function public.check_batch_member();
create trigger batch_mentors_check before insert or update on public.batch_mentors
  for each row execute function public.check_batch_member();

-- ---------------------------------------------------------------------------
-- 3. Scope helpers (SECURITY DEFINER: no RLS recursion)
-- ---------------------------------------------------------------------------

create function public.is_batch_mentor(p_batch uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.batch_mentors where batch_id = p_batch and mentor_id = auth.uid())
$$;

-- True when the caller mentors a batch that p_person is a student or mentor of.
create function public.is_batch_peer(p_person uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.batch_mentors mine
    where mine.mentor_id = auth.uid()
      and (
        exists (select 1 from public.batch_students s where s.batch_id = mine.batch_id and s.student_id = p_person)
        or exists (select 1 from public.batch_mentors m where m.batch_id = mine.batch_id and m.mentor_id = p_person)
      )
  )
$$;

create function public.batch_academy(p_batch uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select academy_id from public.batches where id = p_batch
$$;

-- ---------------------------------------------------------------------------
-- 4. RLS
-- ---------------------------------------------------------------------------

-- Academy admins manage membership of their own academy's batches.
create policy "batch_students_admin" on public.batch_students
  for all
  using (public.batch_academy(batch_id) = public.current_admin_academy_id())
  with check (public.batch_academy(batch_id) = public.current_admin_academy_id());

create policy "batch_mentors_admin" on public.batch_mentors
  for all
  using (public.batch_academy(batch_id) = public.current_admin_academy_id())
  with check (public.batch_academy(batch_id) = public.current_admin_academy_id());

-- Mentors read their own batches' rosters; students read their own row.
create policy "batch_students_mentor_read" on public.batch_students
  for select using (public.is_batch_mentor(batch_id));
create policy "batch_students_own_read" on public.batch_students
  for select using (student_id = auth.uid());
create policy "batch_mentors_mentor_read" on public.batch_mentors
  for select using (public.is_batch_mentor(batch_id));

-- Super admins read everything (platform oversight).
create policy "batch_students_super_read" on public.batch_students for select using (public.is_super_admin());
create policy "batch_mentors_super_read" on public.batch_mentors for select using (public.is_super_admin());
create policy "batches_select_super_admin" on public.batches for select using (public.is_super_admin());

-- Mentors see the batches they're assigned to.
create policy "batches_select_mentor" on public.batches
  for select using (public.is_batch_mentor(id));

-- Mentors see the profiles of their batches' students and co-mentors only.
create policy "profiles_select_batch_peer" on public.profiles
  for select using (public.is_batch_peer(id));

-- ---------------------------------------------------------------------------
-- 5. Read views (security invoker: each caller's RLS still applies)
-- ---------------------------------------------------------------------------

create view public.batch_overview
with (security_invoker = true) as
  select
    b.id,
    b.academy_id,
    b.name,
    b.status,
    b.start_date,
    b.created_at,
    coalesce(array_agg(bm.mentor_id order by p.full_name) filter (where bm.mentor_id is not null), '{}') as mentor_ids,
    coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) order by p.full_name) filter (where p.id is not null), '[]'::jsonb) as mentors,
    count(bm.mentor_id) as mentor_count,
    (select count(*) from public.batch_students s where s.batch_id = b.id) as student_count
  from public.batches b
  left join public.batch_mentors bm on bm.batch_id = b.id
  left join public.profiles p on p.id = bm.mentor_id
  group by b.id;

create view public.academy_students
with (security_invoker = true) as
  select
    p.id,
    p.full_name,
    p.email,
    p.status,
    p.academy_id,
    p.last_login_at,
    p.created_at,
    bs.batch_id,
    b.name as batch_name
  from public.profiles p
  left join public.batch_students bs on bs.student_id = p.id
  left join public.batches b on b.id = bs.batch_id
  where p.role = 'student';

grant select on public.batch_overview to authenticated;
grant select on public.academy_students to authenticated;

-- ---------------------------------------------------------------------------
-- 6. Academy admins add / remove students of THEIR academy
-- ---------------------------------------------------------------------------

-- The 0005 guard rejects privileged profile changes from anyone but a super
-- admin. The functions below are the only other sanctioned path: they set a
-- transaction-local flag first. set_config lives in pg_catalog, which the API
-- doesn't expose, so a client can't set this flag itself.
create or replace function public.guard_profile_update()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  privileged_changed boolean :=
    new.role is distinct from old.role
    or new.academy_id is distinct from old.academy_id
    or new.status is distinct from old.status
    or new.email is distinct from old.email
    or new.last_login_at is distinct from old.last_login_at
    or new.id is distinct from old.id;
  trusted boolean := coalesce(current_setting('app.trusted_change', true), '') = 'on';
begin
  if auth.uid() is not null and privileged_changed and not trusted then
    if not public.is_super_admin() then
      raise exception 'only a super admin can change role, academy, status or email'
        using errcode = '42501';
    end if;
    if old.id = auth.uid() and (new.role is distinct from old.role or new.status is distinct from old.status) then
      raise exception 'you cannot change your own role or status'
        using errcode = '42501';
    end if;
  end if;

  new.updated_at := now();
  if new.role is distinct from old.role then
    perform public.ensure_role_profile(new.id, new.role);
  end if;
  return new;
end;
$$;

-- Returns the student's id and name. Only takes accounts with no academy (or
-- already in the caller's): never pulls a student out of another academy.
create function public.academy_add_student(p_email text)
returns table (id uuid, full_name text)
language plpgsql
security definer set search_path = public
as $$
declare
  my_academy uuid := public.current_admin_academy_id();
  target public.profiles%rowtype;
begin
  if my_academy is null then
    raise exception 'only an academy admin can add students' using errcode = '42501';
  end if;
  select * into target from public.profiles where lower(email) = lower(btrim(p_email));
  if not found then
    raise exception 'no account uses that email' using errcode = 'P0002';
  end if;
  if target.role <> 'student' then
    raise exception 'that account is not a student' using errcode = '23514';
  end if;
  if target.academy_id is not null and target.academy_id <> my_academy then
    raise exception 'that student belongs to another academy' using errcode = '23505';
  end if;
  perform set_config('app.trusted_change', 'on', true);
  update public.profiles set academy_id = my_academy where profiles.id = target.id;
  insert into public.audit_log (actor_id, action, target_type, target_id, details)
  values (auth.uid(), 'academy.student_added', 'user', target.id, jsonb_build_object('summary', 'Added to academy by an academy admin'));
  return query select target.id, target.full_name;
end;
$$;

create function public.academy_remove_student(p_student uuid)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  my_academy uuid := public.current_admin_academy_id();
begin
  if my_academy is null then
    raise exception 'only an academy admin can remove students' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_student and role = 'student' and academy_id = my_academy) then
    raise exception 'not a student of your academy' using errcode = 'P0002';
  end if;
  delete from public.batch_students where student_id = p_student;
  perform set_config('app.trusted_change', 'on', true);
  update public.profiles set academy_id = null where id = p_student;
  insert into public.audit_log (actor_id, action, target_type, target_id, details)
  values (auth.uid(), 'academy.student_removed', 'user', p_student, jsonb_build_object('summary', 'Removed from academy by an academy admin'));
end;
$$;

revoke execute on function public.academy_add_student(text) from public, anon;
revoke execute on function public.academy_remove_student(uuid) from public, anon;
grant execute on function public.academy_add_student(text) to authenticated;
grant execute on function public.academy_remove_student(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 7. Invited students join their academy (extends the 0005 signup trigger)
-- ---------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  app_role text := new.raw_app_meta_data->>'role';        -- service-role only
  meta_role text := new.raw_user_meta_data->>'role';      -- browser-controlled
  signup_role public.user_role;
  new_academy_id uuid;
  trusted_academy text;
begin
  if app_role in ('student', 'mentor', 'academy_admin', 'super_admin') then
    signup_role := app_role::public.user_role;
    trusted_academy := new.raw_app_meta_data->>'academy_id';
  elsif meta_role in ('mentor', 'student') and new.invited_at is not null then
    -- inviteUserByEmail (server-side, service role) is the only way to get here.
    signup_role := meta_role::public.user_role;
    trusted_academy := new.raw_user_meta_data->>'academy_id';
  elsif meta_role = 'academy_admin' then
    signup_role := 'academy_admin';
  else
    signup_role := 'student';
  end if;

  if signup_role = 'academy_admin' and trusted_academy is null then
    insert into public.academies (name, owner_id)
    values (coalesce(nullif(btrim(new.raw_user_meta_data->>'academy_name'), ''), 'My Academy'), new.id)
    returning id into new_academy_id;
  elsif trusted_academy is not null then
    new_academy_id := trusted_academy::uuid;
  end if;

  insert into public.profiles (id, role, full_name, academy_id, email, last_login_at)
  values (new.id, signup_role, coalesce(new.raw_user_meta_data->>'full_name', ''), new_academy_id, new.email, new.last_sign_in_at);

  perform public.ensure_role_profile(new.id, signup_role);
  return new;
end;
$$;

-- ===========================================================================
-- 0008_contents.sql
-- ===========================================================================
-- SSB Academy — Phase 4 (T083): global learning content.
-- Run once in the Supabase SQL Editor, AFTER 0004–0007.
--
-- Design notes
--  * contents holds platform content now. owner_type/owner_id already leave
--    room for mentor-owned content (Phase 5) without a second table, but
--    Phase 4 only ever writes owner_type = 'platform'.
--  * Content is never deleted: status moves draft → published → archived.
--  * Readers see ONLY published content for their role, either visible to
--    everyone or assigned to their academy / their batch. That rule lives in
--    can_read_content() and is enforced by RLS, not by the UI.

create type public.content_category as enum ('psychology', 'gto', 'interview', 'communication', 'current_affairs', 'general');
create type public.content_type as enum ('study_material', 'video', 'document', 'article', 'practice_exercise', 'assessment', 'session_template', 'mock_activity');
create type public.content_difficulty as enum ('easy', 'medium', 'hard');
create type public.content_audience as enum ('student', 'mentor', 'both');
create type public.content_visibility as enum ('everyone', 'assigned');
create type public.content_status as enum ('draft', 'published', 'archived');
create type public.content_owner as enum ('platform', 'mentor');

create table public.contents (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  category public.content_category not null,
  type public.content_type not null,
  difficulty public.content_difficulty not null default 'medium',
  target_role public.content_audience not null default 'student',
  visibility public.content_visibility not null default 'everyone',
  status public.content_status not null default 'draft',
  body text,
  external_url text,
  owner_type public.content_owner not null default 'platform',
  owner_id uuid references public.profiles(id) on delete set null,
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  constraint contents_title_length check (char_length(btrim(title)) between 3 and 140),
  constraint contents_url_https check (external_url is null or external_url ~ '^https://'),
  constraint contents_has_substance check (coalesce(btrim(body), '') <> '' or external_url is not null)
);

create index contents_status_idx on public.contents (status);
create index contents_category_idx on public.contents (category);
create index contents_owner_idx on public.contents (owner_type, owner_id);
create index contents_updated_idx on public.contents (updated_at desc);

create table public.content_assignments (
  id uuid primary key default gen_random_uuid(),
  content_id uuid not null references public.contents(id) on delete cascade,
  academy_id uuid references public.academies(id) on delete cascade,
  batch_id uuid references public.batches(id) on delete cascade,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint content_assignments_one_target check ((academy_id is null) <> (batch_id is null))
);

create unique index content_assignments_academy_unique on public.content_assignments (content_id, academy_id) where academy_id is not null;
create unique index content_assignments_batch_unique on public.content_assignments (content_id, batch_id) where batch_id is not null;
create index content_assignments_academy_idx on public.content_assignments (academy_id);
create index content_assignments_batch_idx on public.content_assignments (batch_id);

alter table public.contents enable row level security;
alter table public.content_assignments enable row level security;

-- Keep updated_at / published_at honest regardless of what the client sends.
create function public.touch_content()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
    new.published_at := now();
  end if;
  return new;
end;
$$;

create trigger contents_touch before insert or update on public.contents
  for each row execute function public.touch_content();

-- The reading rule (SECURITY DEFINER: reads batches/memberships without RLS
-- recursion). Super admins are handled by their own policy.
create function public.can_read_content(p_content uuid)
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (
    select 1
    from public.contents c
    join public.profiles me on me.id = auth.uid() and me.status = 'active'
    where c.id = p_content
      and c.status = 'published'
      and (
        c.target_role = 'both'
        or (c.target_role = 'student' and me.role in ('student', 'academy_admin'))
        or (c.target_role = 'mentor' and me.role in ('mentor', 'academy_admin'))
      )
      and (
        c.visibility = 'everyone'
        or exists (
          select 1 from public.content_assignments a
          where a.content_id = c.id
            and (
              (a.academy_id is not null and a.academy_id = me.academy_id)
              or (a.batch_id is not null and (
                exists (select 1 from public.batch_students s where s.batch_id = a.batch_id and s.student_id = me.id)
                or exists (select 1 from public.batch_mentors m where m.batch_id = a.batch_id and m.mentor_id = me.id)
                or public.batch_academy(a.batch_id) = public.current_admin_academy_id()
              ))
            )
        )
      )
  )
$$;

create policy "contents_super_admin_read" on public.contents for select using (public.is_super_admin());
create policy "contents_super_admin_insert" on public.contents
  for insert with check (public.is_super_admin() and owner_type = 'platform' and created_by = auth.uid());
create policy "contents_super_admin_update" on public.contents
  for update using (public.is_super_admin() and owner_type = 'platform') with check (public.is_super_admin() and owner_type = 'platform');
create policy "contents_reader_read" on public.contents for select using (public.can_read_content(id));

create policy "content_assignments_super_admin" on public.content_assignments
  for all using (public.is_super_admin()) with check (public.is_super_admin());

-- ===========================================================================
-- 0009_mentor_content.sql
-- ===========================================================================
-- SSB Academy — Phase 5 (T084): mentor content, starter templates and
-- content requests. Run once in the Supabase SQL Editor, AFTER 0004–0008.
--
-- Design notes
--  * Mentor content lives in the same `contents` table (owner_type = 'mentor',
--    owner_id = the mentor). A trigger pins it to visibility 'assigned' and
--    audience 'student', so it only ever reaches batches it's assigned to.
--  * Mentors assign their content only to batches they teach (is_batch_mentor).
--  * Templates: platform content with is_template = true; any mentor can read
--    published templates (to copy them). Copies remember template_source_id.
--  * content_requests: a paid "create it for me" service. Mentors only create
--    requests and respond to quotes, through SECURITY DEFINER functions that
--    enforce the lifecycle. The fee is recorded, never charged: settlement
--    happens outside the app and is marked by a super admin.

-- ---------------------------------------------------------------------------
-- 1. Templates + mentor ownership on contents
-- ---------------------------------------------------------------------------

alter table public.contents
  add column is_template boolean not null default false,
  add column template_source_id uuid references public.contents(id) on delete set null;

alter table public.contents
  add constraint contents_template_platform_only check (not is_template or owner_type = 'platform'),
  add constraint contents_mentor_has_owner check (owner_type = 'platform' or owner_id is not null);

create index contents_template_idx on public.contents (is_template) where is_template;

create function public.pin_mentor_content()
returns trigger
language plpgsql
as $$
begin
  if new.owner_type = 'mentor' then
    new.visibility := 'assigned';
    new.target_role := 'student';
    new.is_template := false;
  end if;
  return new;
end;
$$;

create trigger contents_pin_mentor before insert or update on public.contents
  for each row execute function public.pin_mentor_content();

-- Mentors: full control of their OWN content only (no delete: archive instead).
create policy "contents_mentor_own_read" on public.contents
  for select using (owner_type = 'mentor' and owner_id = auth.uid());

create policy "contents_mentor_own_insert" on public.contents
  for insert with check (
    owner_type = 'mentor' and owner_id = auth.uid() and created_by = auth.uid()
    and public.current_user_role() = 'mentor'
  );

create policy "contents_mentor_own_update" on public.contents
  for update
  using (owner_type = 'mentor' and owner_id = auth.uid())
  with check (owner_type = 'mentor' and owner_id = auth.uid());

-- Mentors read published templates (to copy them), whatever their audience.
create policy "contents_mentor_templates_read" on public.contents
  for select using (
    is_template and status = 'published' and owner_type = 'platform'
    and public.current_user_role() = 'mentor'
  );

-- Mentors assign their own content to batches they teach; they can always
-- remove assignments from their own content.
create function public.owns_content(p_content uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.contents where id = p_content and owner_type = 'mentor' and owner_id = auth.uid())
$$;

create policy "content_assignments_mentor_read" on public.content_assignments
  for select using (public.owns_content(content_id));

create policy "content_assignments_mentor_insert" on public.content_assignments
  for insert with check (
    public.owns_content(content_id) and academy_id is null and batch_id is not null
    and public.is_batch_mentor(batch_id) and created_by = auth.uid()
  );

create policy "content_assignments_mentor_delete" on public.content_assignments
  for delete using (public.owns_content(content_id));

-- ---------------------------------------------------------------------------
-- 2. Content requests (paid service, settled outside the app)
-- ---------------------------------------------------------------------------

create type public.content_request_status as enum ('requested', 'quoted', 'accepted', 'declined', 'in_progress', 'delivered', 'cancelled');
create type public.settlement_status as enum ('not_due', 'owed', 'settled');

create table public.content_requests (
  id uuid primary key default gen_random_uuid(),
  mentor_id uuid not null references public.profiles(id) on delete cascade,
  academy_id uuid references public.academies(id) on delete set null,
  title text not null,
  details text not null,
  category public.content_category not null,
  type public.content_type not null,
  needed_by date,
  status public.content_request_status not null default 'requested',
  quoted_fee_inr numeric(10, 2),
  quote_note text,
  quoted_at timestamptz,
  responded_at timestamptz,
  delivered_content_id uuid references public.contents(id) on delete set null,
  delivered_at timestamptz,
  settlement public.settlement_status not null default 'not_due',
  settled_at timestamptz,
  settled_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint content_requests_title_length check (char_length(btrim(title)) between 3 and 140),
  constraint content_requests_details_length check (char_length(btrim(details)) between 10 and 4000),
  constraint content_requests_fee_positive check (quoted_fee_inr is null or (quoted_fee_inr > 0 and quoted_fee_inr <= 10000000))
);

create index content_requests_mentor_idx on public.content_requests (mentor_id, created_at desc);
create index content_requests_status_idx on public.content_requests (status, created_at desc);

alter table public.content_requests enable row level security;

create function public.touch_content_request()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger content_requests_touch before update on public.content_requests
  for each row execute function public.touch_content_request();

-- Mentors read and create their own requests; super admins read all and do
-- every staff-side transition (quote, progress, deliver, settle) — the
-- service enforces the lifecycle; mentors' own transitions go through the
-- functions below, never a direct update.
create policy "content_requests_mentor_read" on public.content_requests
  for select using (mentor_id = auth.uid());
create policy "content_requests_mentor_insert" on public.content_requests
  for insert with check (
    mentor_id = auth.uid() and status = 'requested' and quoted_fee_inr is null
    and settlement = 'not_due' and public.current_user_role() = 'mentor'
  );
create policy "content_requests_super_read" on public.content_requests
  for select using (public.is_super_admin());
create policy "content_requests_super_update" on public.content_requests
  for update using (public.is_super_admin()) with check (public.is_super_admin());

-- Mentor: accept or decline a quote (only their own, only while quoted).
create function public.respond_to_content_quote(p_request uuid, p_accept boolean)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  update public.content_requests
  set status = case when p_accept then 'accepted'::public.content_request_status else 'declined'::public.content_request_status end,
      settlement = case when p_accept then 'owed'::public.settlement_status else 'not_due'::public.settlement_status end,
      responded_at = now()
  where id = p_request and mentor_id = auth.uid() and status = 'quoted';
  if not found then
    raise exception 'this request is not waiting for your answer' using errcode = 'P0002';
  end if;
end;
$$;

-- Mentor: cancel before accepting.
create function public.cancel_content_request(p_request uuid)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  update public.content_requests
  set status = 'cancelled'
  where id = p_request and mentor_id = auth.uid() and status in ('requested', 'quoted');
  if not found then
    raise exception 'this request can no longer be cancelled' using errcode = 'P0002';
  end if;
end;
$$;

-- Super admin: deliver = copy a platform content item into the mentor's own
-- content (as a draft) and close the request, in one transaction.
create function public.deliver_content_request(p_request uuid, p_content uuid)
returns uuid
language plpgsql
security definer set search_path = public
as $$
declare
  req public.content_requests%rowtype;
  src public.contents%rowtype;
  new_id uuid;
begin
  if not public.is_super_admin() then
    raise exception 'only a super admin can deliver requests' using errcode = '42501';
  end if;
  select * into req from public.content_requests where id = p_request for update;
  if not found or req.status not in ('accepted', 'in_progress') then
    raise exception 'only an accepted request can be delivered' using errcode = 'P0002';
  end if;
  select * into src from public.contents where id = p_content and owner_type = 'platform';
  if not found then
    raise exception 'choose platform content to deliver' using errcode = 'P0002';
  end if;

  insert into public.contents (title, description, category, type, difficulty, target_role, visibility, status, body, external_url, owner_type, owner_id, template_source_id, created_by, updated_by)
  values (src.title, src.description, src.category, src.type, src.difficulty, 'student', 'assigned', 'draft', src.body, src.external_url, 'mentor', req.mentor_id, src.id, auth.uid(), auth.uid())
  returning id into new_id;

  update public.content_requests
  set status = 'delivered', delivered_content_id = new_id, delivered_at = now()
  where id = p_request;

  insert into public.audit_log (actor_id, action, target_type, target_id, details)
  values (auth.uid(), 'content_request.delivered', 'content_request', p_request, jsonb_build_object('summary', 'Delivered to the mentor''s My Content', 'contentId', new_id));
  return new_id;
end;
$$;

revoke execute on function public.respond_to_content_quote(uuid, boolean) from public, anon;
revoke execute on function public.cancel_content_request(uuid) from public, anon;
revoke execute on function public.deliver_content_request(uuid, uuid) from public, anon;
grant execute on function public.respond_to_content_quote(uuid, boolean) to authenticated;
grant execute on function public.cancel_content_request(uuid) to authenticated;
grant execute on function public.deliver_content_request(uuid, uuid) to authenticated;

-- ===========================================================================
-- 0010_sessions.sql
-- ===========================================================================
-- SSB Academy — Phase 6 (T085): mentor availability and sessions.
-- Run once in the Supabase SQL Editor, AFTER 0004–0009.
--
-- Design notes
--  * A session belongs to ONE batch and ONE mentor who teaches that batch.
--    Audience: the whole batch, or only the students listed in
--    session_participants (who must be in that batch).
--  * No double-booking: an exclusion constraint stops two overlapping
--    *scheduled* sessions for the same mentor (needs btree_gist).
--  * Visibility lives in can_see_session() and RLS: the mentor, the batch's
--    students (or the selected ones), the academy's admins, super admins.
--  * Times are timestamptz (UTC); the app shows them in IST.

create extension if not exists btree_gist;

-- ---------------------------------------------------------------------------
-- 1. Availability (weekly slots)
-- ---------------------------------------------------------------------------

create table public.mentor_availability (
  id uuid primary key default gen_random_uuid(),
  mentor_id uuid not null references public.profiles(id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6), -- 0 = Sunday
  start_time time not null,
  end_time time not null,
  created_at timestamptz not null default now(),
  constraint mentor_availability_order check (end_time > start_time)
);

create index mentor_availability_mentor_idx on public.mentor_availability (mentor_id, weekday, start_time);

alter table public.mentor_availability enable row level security;

create policy "availability_mentor_own" on public.mentor_availability
  for all
  using (mentor_id = auth.uid())
  with check (mentor_id = auth.uid() and public.current_user_role() = 'mentor');

create policy "availability_academy_admin_read" on public.mentor_availability
  for select using (
    exists (select 1 from public.profiles p where p.id = mentor_id and p.academy_id = public.current_admin_academy_id())
  );

-- ---------------------------------------------------------------------------
-- 2. Sessions
-- ---------------------------------------------------------------------------

create type public.session_mode as enum ('online', 'offline');
create type public.session_status as enum ('scheduled', 'completed', 'cancelled');

create table public.sessions (
  id uuid primary key default gen_random_uuid(),
  academy_id uuid not null references public.academies(id) on delete cascade,
  batch_id uuid not null references public.batches(id) on delete cascade,
  mentor_id uuid not null references public.profiles(id) on delete cascade,
  title text not null,
  description text,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  mode public.session_mode not null,
  meeting_url text,
  location text,
  for_whole_batch boolean not null default true,
  status public.session_status not null default 'scheduled',
  cancel_reason text,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sessions_title_length check (char_length(btrim(title)) between 3 and 140),
  constraint sessions_time_order check (ends_at > starts_at and ends_at - starts_at <= interval '8 hours'),
  constraint sessions_mode_details check (
    (mode = 'online' and meeting_url ~ '^https://')
    or (mode = 'offline' and coalesce(btrim(location), '') <> '')
  ),
  constraint sessions_cancel_reason check (status <> 'cancelled' or coalesce(btrim(cancel_reason), '') <> ''),
  constraint sessions_no_overlap exclude using gist (
    mentor_id with =,
    tstzrange(starts_at, ends_at) with &&
  ) where (status = 'scheduled')
);

create index sessions_batch_idx on public.sessions (batch_id, starts_at);
create index sessions_mentor_idx on public.sessions (mentor_id, starts_at);
create index sessions_academy_idx on public.sessions (academy_id, starts_at);

create table public.session_participants (
  session_id uuid not null references public.sessions(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  primary key (session_id, student_id)
);

create index session_participants_student_idx on public.session_participants (student_id);

alter table public.sessions enable row level security;
alter table public.session_participants enable row level security;

-- Keep academy_id consistent with the batch, and updated_at honest.
create function public.prepare_session()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  new.academy_id := (select academy_id from public.batches where id = new.batch_id);
  new.updated_at := now();
  return new;
end;
$$;

create trigger sessions_prepare before insert or update on public.sessions
  for each row execute function public.prepare_session();

-- Selected participants must be students of the session's batch.
create function public.check_session_participant()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  if not exists (
    select 1 from public.sessions s
    join public.batch_students bs on bs.batch_id = s.batch_id and bs.student_id = new.student_id
    where s.id = new.session_id
  ) then
    raise exception 'participants must be students of the session''s batch' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger session_participants_check before insert or update on public.session_participants
  for each row execute function public.check_session_participant();

-- The visibility rule.
create function public.can_see_session(p_session uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.sessions s
    where s.id = p_session
      and (
        s.mentor_id = auth.uid()
        or s.academy_id = public.current_admin_academy_id()
        or public.is_super_admin()
        or (s.for_whole_batch and exists (select 1 from public.batch_students bs where bs.batch_id = s.batch_id and bs.student_id = auth.uid()))
        or (not s.for_whole_batch and exists (select 1 from public.session_participants sp where sp.session_id = s.id and sp.student_id = auth.uid()))
      )
  )
$$;

create policy "sessions_read" on public.sessions for select using (public.can_see_session(id));

-- Mentors write only their own sessions, only for batches they teach.
create policy "sessions_mentor_insert" on public.sessions
  for insert with check (mentor_id = auth.uid() and created_by = auth.uid() and public.is_batch_mentor(batch_id));
create policy "sessions_mentor_update" on public.sessions
  for update using (mentor_id = auth.uid()) with check (mentor_id = auth.uid() and public.is_batch_mentor(batch_id));

create policy "session_participants_read" on public.session_participants
  for select using (public.can_see_session(session_id));
create policy "session_participants_mentor_write" on public.session_participants
  for all
  using (exists (select 1 from public.sessions s where s.id = session_id and s.mentor_id = auth.uid()))
  with check (exists (select 1 from public.sessions s where s.id = session_id and s.mentor_id = auth.uid()));

-- ===========================================================================
-- 0011_assessments.sql
-- ===========================================================================
-- SSB Academy — Phase 7 (T086): assessments, attempts and mentor feedback.
-- Run once in the Supabase SQL Editor, AFTER 0004–0010.
--
-- Design notes
--  * An assessment belongs to ONE batch and is created by a mentor who
--    teaches it. Questions are a small JSON array of {id, prompt}; answers are
--    free text (the MVP is text-based, specs.md §6.4).
--  * One attempt per (assessment, student). Students write their own attempt
--    only while it's a draft AND the assessment is published and not past due;
--    once submitted it's locked (enforced by RLS + a trigger).
--  * One feedback per attempt (unique), written by a mentor of the batch.
--    'in_review' = draft (staff only), 'reviewed' = final, locked, visible to
--    the student. The unique key makes a double submit idempotent.

create type public.assessment_status as enum ('draft', 'published', 'closed');
create type public.attempt_status as enum ('draft', 'submitted');
create type public.feedback_status as enum ('in_review', 'reviewed');

create table public.assessments (
  id uuid primary key default gen_random_uuid(),
  academy_id uuid not null references public.academies(id) on delete cascade,
  batch_id uuid not null references public.batches(id) on delete cascade,
  mentor_id uuid not null references public.profiles(id) on delete cascade,
  title text not null,
  instructions text,
  category public.content_category not null default 'general',
  questions jsonb not null,
  max_score smallint not null default 10,
  due_at timestamptz,
  status public.assessment_status not null default 'draft',
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint assessments_title_length check (char_length(btrim(title)) between 3 and 140),
  constraint assessments_max_score check (max_score between 1 and 100),
  constraint assessments_questions_shape check (jsonb_typeof(questions) = 'array' and jsonb_array_length(questions) between 1 and 20)
);

create index assessments_batch_idx on public.assessments (batch_id, created_at desc);
create index assessments_mentor_idx on public.assessments (mentor_id, created_at desc);

create table public.assessment_attempts (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references public.assessments(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  answers jsonb not null default '[]'::jsonb,
  status public.attempt_status not null default 'draft',
  submitted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint attempts_one_per_student unique (assessment_id, student_id),
  constraint attempts_answers_shape check (jsonb_typeof(answers) = 'array')
);

create index attempts_student_idx on public.assessment_attempts (student_id);

create table public.feedback (
  id uuid primary key default gen_random_uuid(),
  attempt_id uuid not null unique references public.assessment_attempts(id) on delete cascade,
  mentor_id uuid not null references public.profiles(id) on delete cascade,
  score numeric(5, 2),
  strengths text,
  improvement_areas text,
  comments text,
  status public.feedback_status not null default 'in_review',
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint feedback_reviewed_complete check (
    status <> 'reviewed'
    or (score is not null and coalesce(btrim(strengths), '') <> '' and coalesce(btrim(improvement_areas), '') <> '')
  )
);

alter table public.assessments enable row level security;
alter table public.assessment_attempts enable row level security;
alter table public.feedback enable row level security;

-- ---------------------------------------------------------------------------
-- Triggers: derived fields + lifecycle locks
-- ---------------------------------------------------------------------------

create function public.prepare_assessment()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  new.academy_id := (select academy_id from public.batches where id = new.batch_id);
  new.updated_at := now();
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
    new.published_at := coalesce(new.published_at, now());
  end if;
  -- Questions can't change once students may have answered them.
  if tg_op = 'UPDATE' and old.status <> 'draft' and new.questions is distinct from old.questions then
    raise exception 'questions are locked once an assessment is published' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger assessments_prepare before insert or update on public.assessments
  for each row execute function public.prepare_assessment();

create function public.guard_attempt()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  a public.assessments%rowtype;
begin
  if tg_op = 'UPDATE' and old.status = 'submitted' then
    raise exception 'a submitted attempt is locked' using errcode = '23514';
  end if;
  select * into a from public.assessments where id = new.assessment_id;
  if a.status <> 'published' or (a.due_at is not null and a.due_at < now()) then
    raise exception 'this assessment is not open for answers' using errcode = '23514';
  end if;
  if not exists (select 1 from public.batch_students bs where bs.batch_id = a.batch_id and bs.student_id = new.student_id) then
    raise exception 'only students of the batch can answer' using errcode = '23514';
  end if;
  new.updated_at := now();
  if new.status = 'submitted' then
    new.submitted_at := now();
  end if;
  return new;
end;
$$;

create trigger attempts_guard before insert or update on public.assessment_attempts
  for each row execute function public.guard_attempt();

create function public.guard_feedback()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  max_s smallint;
  att_status public.attempt_status;
begin
  if tg_op = 'UPDATE' and old.status = 'reviewed' then
    raise exception 'reviewed feedback is locked' using errcode = '23514';
  end if;
  select a.max_score, t.status into max_s, att_status
  from public.assessment_attempts t join public.assessments a on a.id = t.assessment_id
  where t.id = new.attempt_id;
  if att_status is distinct from 'submitted' then
    raise exception 'only a submitted attempt can be evaluated' using errcode = '23514';
  end if;
  if new.score is not null and (new.score < 0 or new.score > max_s) then
    raise exception 'score must be between 0 and the maximum' using errcode = '23514';
  end if;
  new.updated_at := now();
  if new.status = 'reviewed' then
    new.reviewed_at := now();
  end if;
  return new;
end;
$$;

create trigger feedback_guard before insert or update on public.feedback
  for each row execute function public.guard_feedback();

-- ---------------------------------------------------------------------------
-- Scope helpers
-- ---------------------------------------------------------------------------

create function public.assessment_batch(p_assessment uuid)
returns uuid
language sql stable security definer set search_path = public
as $$ select batch_id from public.assessments where id = p_assessment $$;

create function public.attempt_batch(p_attempt uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select a.batch_id from public.assessment_attempts t join public.assessments a on a.id = t.assessment_id where t.id = p_attempt
$$;

create function public.attempt_owner(p_attempt uuid)
returns uuid
language sql stable security definer set search_path = public
as $$ select student_id from public.assessment_attempts where id = p_attempt $$;

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------

-- Assessments
create policy "assessments_mentor_read" on public.assessments for select using (public.is_batch_mentor(batch_id));
create policy "assessments_mentor_insert" on public.assessments
  for insert with check (mentor_id = auth.uid() and public.is_batch_mentor(batch_id));
create policy "assessments_mentor_update" on public.assessments
  for update using (public.is_batch_mentor(batch_id)) with check (public.is_batch_mentor(batch_id));
create policy "assessments_student_read" on public.assessments
  for select using (
    status <> 'draft'
    and exists (select 1 from public.batch_students bs where bs.batch_id = assessments.batch_id and bs.student_id = auth.uid())
  );
create policy "assessments_admin_read" on public.assessments
  for select using (academy_id = public.current_admin_academy_id() or public.is_super_admin());

-- Attempts
create policy "attempts_student_own_read" on public.assessment_attempts for select using (student_id = auth.uid());
create policy "attempts_student_insert" on public.assessment_attempts
  for insert with check (student_id = auth.uid());
create policy "attempts_student_update" on public.assessment_attempts
  for update using (student_id = auth.uid() and status = 'draft') with check (student_id = auth.uid());
create policy "attempts_mentor_read" on public.assessment_attempts
  for select using (status = 'submitted' and public.is_batch_mentor(public.assessment_batch(assessment_id)));
create policy "attempts_admin_read" on public.assessment_attempts
  for select using (public.batch_academy(public.assessment_batch(assessment_id)) = public.current_admin_academy_id() or public.is_super_admin());

-- Feedback
create policy "feedback_mentor_read" on public.feedback for select using (public.is_batch_mentor(public.attempt_batch(attempt_id)));
create policy "feedback_mentor_insert" on public.feedback
  for insert with check (mentor_id = auth.uid() and public.is_batch_mentor(public.attempt_batch(attempt_id)));
create policy "feedback_mentor_update" on public.feedback
  for update using (public.is_batch_mentor(public.attempt_batch(attempt_id)) and status = 'in_review')
  with check (mentor_id = auth.uid() and public.is_batch_mentor(public.attempt_batch(attempt_id)));
create policy "feedback_student_read" on public.feedback
  for select using (status = 'reviewed' and public.attempt_owner(attempt_id) = auth.uid());
create policy "feedback_admin_read" on public.feedback
  for select using (public.batch_academy(public.attempt_batch(attempt_id)) = public.current_admin_academy_id() or public.is_super_admin());

-- ===========================================================================
-- 0012_progress.sql
-- ===========================================================================
-- SSB Academy — Phase 8 (T087): progress sources + derived views.
-- Run once in the Supabase SQL Editor, AFTER 0004–0011.
--
-- Design notes
--  * Two new SOURCE tables: session_attendance (marked by the session's
--    mentor) and content_progress (marked by the student). Everything else
--    is derived from existing rows (reviewed feedback, sessions).
--  * Derived data lives in security-invoker VIEWS, not copied tables: one
--    source of truth, and every reader's RLS still applies to the rows the
--    view reads. `student_progress` in the brief is this view.

create type public.attendance_status as enum ('present', 'absent', 'excused');

create table public.session_attendance (
  session_id uuid not null references public.sessions(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  status public.attendance_status not null,
  marked_by uuid references public.profiles(id) on delete set null,
  marked_at timestamptz not null default now(),
  primary key (session_id, student_id)
);

create index session_attendance_student_idx on public.session_attendance (student_id);

create table public.content_progress (
  content_id uuid not null references public.contents(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  completed_at timestamptz not null default now(),
  primary key (content_id, student_id)
);

create index content_progress_student_idx on public.content_progress (student_id);

alter table public.session_attendance enable row level security;
alter table public.content_progress enable row level security;

-- Attendance: only for a participant of the session (the whole batch, or the
-- selected students), only once it has started.
create function public.check_attendance()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  s public.sessions%rowtype;
begin
  select * into s from public.sessions where id = new.session_id;
  if s.starts_at > now() or s.status = 'cancelled' then
    raise exception 'attendance can be marked once the session has started' using errcode = '23514';
  end if;
  if not (
    (s.for_whole_batch and exists (select 1 from public.batch_students bs where bs.batch_id = s.batch_id and bs.student_id = new.student_id))
    or (not s.for_whole_batch and exists (select 1 from public.session_participants sp where sp.session_id = s.id and sp.student_id = new.student_id))
  ) then
    raise exception 'that student is not a participant of this session' using errcode = '23514';
  end if;
  new.marked_at := now();
  return new;
end;
$$;

create trigger session_attendance_check before insert or update on public.session_attendance
  for each row execute function public.check_attendance();

create policy "attendance_mentor_write" on public.session_attendance
  for all
  using (exists (select 1 from public.sessions s where s.id = session_id and s.mentor_id = auth.uid()))
  with check (marked_by = auth.uid() and exists (select 1 from public.sessions s where s.id = session_id and s.mentor_id = auth.uid()));
create policy "attendance_read" on public.session_attendance
  for select using (student_id = auth.uid() or public.can_see_session(session_id) and public.current_user_role() <> 'student');

-- Library completion: the student, for content they can read.
create policy "content_progress_student" on public.content_progress
  for all
  using (student_id = auth.uid())
  with check (student_id = auth.uid() and public.can_read_content(content_id));
create policy "content_progress_staff_read" on public.content_progress
  for select using (
    public.is_batch_peer(student_id)
    or exists (select 1 from public.profiles p where p.id = student_id and p.academy_id = public.current_admin_academy_id())
    or public.is_super_admin()
  );

-- ---------------------------------------------------------------------------
-- Derived views (security invoker)
-- ---------------------------------------------------------------------------

-- One row per reviewed assessment attempt: the score as a percentage.
create view public.student_scores
with (security_invoker = true) as
  select
    t.student_id,
    a.id as assessment_id,
    a.title,
    a.category,
    a.batch_id,
    f.score,
    a.max_score,
    round((f.score / a.max_score) * 100, 1) as score_pct,
    f.improvement_areas,
    f.strengths,
    f.reviewed_at
  from public.feedback f
  join public.assessment_attempts t on t.id = f.attempt_id
  join public.assessments a on a.id = t.assessment_id
  where f.status = 'reviewed' and f.score is not null;

-- Per-student summary — the brief's `student_progress`.
create view public.student_progress
with (security_invoker = true) as
  select
    p.id as student_id,
    p.academy_id,
    bs.batch_id,
    (select count(*) from public.student_scores sc where sc.student_id = p.id) as reviewed_count,
    (select round(avg(sc.score_pct), 1) from public.student_scores sc where sc.student_id = p.id) as avg_score_pct,
    (select count(*) from public.session_attendance a where a.student_id = p.id and a.status = 'present') as sessions_present,
    (select count(*) from public.session_attendance a where a.student_id = p.id and a.status = 'absent') as sessions_absent,
    (select count(*) from public.content_progress c where c.student_id = p.id) as content_completed,
    (select max(t.submitted_at) from public.assessment_attempts t where t.student_id = p.id and t.status = 'submitted') as last_submission_at
  from public.profiles p
  left join public.batch_students bs on bs.student_id = p.id
  where p.role = 'student';

grant select on public.student_scores to authenticated;
grant select on public.student_progress to authenticated;

-- ===========================================================================
-- 0013_notifications_analytics.sql
-- ===========================================================================
-- SSB Academy — Phase 10 (T089): in-app notifications + platform analytics.
-- Run once in the Supabase SQL Editor, AFTER 0004–0012.
--
-- Design notes
--  * Notifications are written by database triggers on the events themselves
--    (session scheduled/cancelled, assessment opened, submission, review,
--    batch membership, content requests). No app code path can forget one,
--    and no client can create one: there is no insert policy.
--  * A recipient can read their own rows and set only `read_at`.
--  * Platform analytics is one SECURITY DEFINER function that refuses anyone
--    but a super admin, so aggregates are computed in SQL without widening
--    any table's RLS.

create type public.notification_kind as enum (
  'session_scheduled',
  'session_cancelled',
  'assessment_published',
  'submission_received',
  'feedback_reviewed',
  'batch_assigned',
  'content_request_new',
  'content_request_update'
);

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references public.profiles(id) on delete cascade,
  kind public.notification_kind not null,
  title text not null,
  body text,
  href text,
  -- The row the event is about (session, assessment, attempt …), for de-duplication.
  ref_id uuid,
  read_at timestamptz,
  created_at timestamptz not null default now(),
  constraint notifications_href_internal check (href is null or href ~ '^/[a-z]')
);

create index notifications_recipient_idx on public.notifications (recipient_id, created_at desc);
create index notifications_unread_idx on public.notifications (recipient_id) where read_at is null;

alter table public.notifications enable row level security;

create policy "notifications_read_own" on public.notifications
  for select using (recipient_id = auth.uid());
create policy "notifications_mark_own" on public.notifications
  for update using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());

-- Only `read_at` is writable by the recipient.
revoke insert, update, delete on public.notifications from authenticated, anon;
grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

-- Internal writer. Not callable through the API.
create function public.notify(p_recipient uuid, p_kind public.notification_kind, p_title text, p_body text, p_href text, p_ref uuid, p_dedupe boolean default true)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  if p_recipient is null then
    return;
  end if;
  if p_dedupe and p_ref is not null and exists (
    select 1 from public.notifications n where n.recipient_id = p_recipient and n.kind = p_kind and n.ref_id = p_ref
  ) then
    return;
  end if;
  insert into public.notifications (recipient_id, kind, title, body, href, ref_id)
  values (p_recipient, p_kind, p_title, p_body, p_href, p_ref);
end;
$$;

revoke execute on function public.notify(uuid, public.notification_kind, text, text, text, uuid, boolean) from public, authenticated, anon;

create function public.ist_label(p_at timestamptz)
returns text
language sql immutable
as $$ select to_char(p_at at time zone 'Asia/Kolkata', 'Dy DD Mon, HH12:MI AM') || ' IST' $$;

-- ---------------------------------------------------------------------------
-- Sessions
-- ---------------------------------------------------------------------------

create function public.notify_session_insert()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  r record;
begin
  if new.for_whole_batch and new.status = 'scheduled' and new.starts_at > now() then
    for r in select student_id from public.batch_students where batch_id = new.batch_id loop
      perform public.notify(r.student_id, 'session_scheduled', 'New session scheduled', new.title || ' · ' || public.ist_label(new.starts_at), '/student/sessions', new.id);
    end loop;
  end if;
  return new;
end;
$$;

create trigger sessions_notify_insert after insert on public.sessions
  for each row execute function public.notify_session_insert();

-- Selected-student sessions: each participant once (edits that rewrite the list don't repeat it).
create function public.notify_session_participant()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  s public.sessions%rowtype;
begin
  select * into s from public.sessions where id = new.session_id;
  if s.status = 'scheduled' and s.starts_at > now() then
    perform public.notify(new.student_id, 'session_scheduled', 'New session scheduled', s.title || ' · ' || public.ist_label(s.starts_at), '/student/sessions', s.id);
  end if;
  return new;
end;
$$;

create trigger session_participants_notify after insert on public.session_participants
  for each row execute function public.notify_session_participant();

create function public.notify_session_cancelled()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  r record;
  msg text := new.title || ' · ' || public.ist_label(new.starts_at);
begin
  if new.status = 'cancelled' and old.status <> 'cancelled' then
    for r in
      select bs.student_id as id from public.batch_students bs where new.for_whole_batch and bs.batch_id = new.batch_id
      union
      select sp.student_id from public.session_participants sp where not new.for_whole_batch and sp.session_id = new.id
    loop
      perform public.notify(r.id, 'session_cancelled', 'Session cancelled', msg, '/student/sessions', new.id);
    end loop;
    for r in select p.id from public.profiles p where p.role = 'academy_admin' and p.academy_id = new.academy_id loop
      perform public.notify(r.id, 'session_cancelled', 'Session cancelled', msg, '/academy/sessions', new.id);
    end loop;
  end if;
  return new;
end;
$$;

create trigger sessions_notify_cancelled after update of status on public.sessions
  for each row execute function public.notify_session_cancelled();

-- ---------------------------------------------------------------------------
-- Assessments, submissions, reviews
-- ---------------------------------------------------------------------------

create function public.notify_assessment_published()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  r record;
begin
  if new.status = 'published' and (tg_op = 'INSERT' or old.status <> 'published') then
    for r in select student_id from public.batch_students where batch_id = new.batch_id loop
      perform public.notify(r.student_id, 'assessment_published', 'New assessment open', new.title, '/student/assessments/' || new.id, new.id);
    end loop;
  end if;
  return new;
end;
$$;

create trigger assessments_notify_published after insert or update of status on public.assessments
  for each row execute function public.notify_assessment_published();

create function public.notify_submission()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  a public.assessments%rowtype;
  who text;
begin
  if new.status = 'submitted' and (tg_op = 'INSERT' or old.status <> 'submitted') then
    select * into a from public.assessments where id = new.assessment_id;
    select coalesce(nullif(full_name, ''), 'A student') into who from public.profiles where id = new.student_id;
    perform public.notify(a.mentor_id, 'submission_received', 'Submission to review', who || ' · ' || a.title, '/mentor/evaluations/' || new.id, new.id);
  end if;
  return new;
end;
$$;

create trigger attempts_notify_submitted after insert or update of status on public.assessment_attempts
  for each row execute function public.notify_submission();

create function public.notify_feedback_reviewed()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  t public.assessment_attempts%rowtype;
  title text;
begin
  if new.status = 'reviewed' and (tg_op = 'INSERT' or old.status <> 'reviewed') then
    select * into t from public.assessment_attempts where id = new.attempt_id;
    select a.title into title from public.assessments a where a.id = t.assessment_id;
    perform public.notify(t.student_id, 'feedback_reviewed', 'Feedback is ready', title, '/student/assessments/' || t.assessment_id, new.id);
  end if;
  return new;
end;
$$;

create trigger feedback_notify_reviewed after insert or update of status on public.feedback
  for each row execute function public.notify_feedback_reviewed();

-- ---------------------------------------------------------------------------
-- Batch membership
-- ---------------------------------------------------------------------------

create function public.notify_batch_member()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  b text;
begin
  select name into b from public.batches where id = new.batch_id;
  if tg_table_name = 'batch_students' then
    perform public.notify(new.student_id, 'batch_assigned', 'You''ve been added to a batch', b, '/student', new.batch_id);
  else
    perform public.notify(new.mentor_id, 'batch_assigned', 'You''re mentoring a batch', b, '/mentor/mentees', new.batch_id);
  end if;
  return new;
end;
$$;

create trigger batch_students_notify after insert on public.batch_students
  for each row execute function public.notify_batch_member();
create trigger batch_mentors_notify after insert on public.batch_mentors
  for each row execute function public.notify_batch_member();

-- ---------------------------------------------------------------------------
-- Content requests (Phase 5)
-- ---------------------------------------------------------------------------

create function public.notify_content_request()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  r record;
begin
  if tg_op = 'INSERT' then
    for r in select id from public.profiles where role = 'super_admin' loop
      perform public.notify(r.id, 'content_request_new', 'New content request', new.title, '/admin/content-requests', new.id);
    end loop;
  elsif new.status <> old.status then
    -- One per status change, so no de-duplication here.
    perform public.notify(new.mentor_id, 'content_request_update', 'Content request ' || replace(new.status::text, '_', ' '), new.title, '/mentor/content/requests', new.id, false);
  end if;
  return new;
end;
$$;

create trigger content_requests_notify after insert or update of status on public.content_requests
  for each row execute function public.notify_content_request();

-- ---------------------------------------------------------------------------
-- Platform analytics (Super Admin only)
-- ---------------------------------------------------------------------------

create function public.platform_analytics(p_since timestamptz)
returns jsonb
language plpgsql
stable
security definer set search_path = public
as $$
declare
  result jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  with
  scores as (
    select t.student_id, a.academy_id, f.reviewed_at, (f.score / a.max_score) * 100 as pct
    from public.feedback f
    join public.assessment_attempts t on t.id = f.attempt_id
    join public.assessments a on a.id = t.assessment_id
    where f.status = 'reviewed' and f.score is not null
  ),
  att as (
    select s.academy_id, sa.status, sa.marked_at
    from public.session_attendance sa
    join public.sessions s on s.id = sa.session_id
  ),
  per_academy as (
    select
      ac.id, ac.name, ac.status,
      (select count(*) from public.profiles p where p.academy_id = ac.id and p.role = 'student') as students,
      (select count(*) from public.profiles p where p.academy_id = ac.id and p.role = 'mentor') as mentors,
      (select count(*) from public.batches b where b.academy_id = ac.id and b.status = 'active') as batches,
      (select count(*) from public.sessions s where s.academy_id = ac.id and s.status <> 'cancelled' and s.ends_at between p_since and now()) as sessions_held,
      (select count(*) from public.assessment_attempts t join public.assessments a on a.id = t.assessment_id
         where a.academy_id = ac.id and t.status = 'submitted' and t.submitted_at >= p_since) as submissions,
      (select count(*) from scores sc where sc.academy_id = ac.id and sc.reviewed_at >= p_since) as reviews,
      (select round(avg(sc.pct), 1) from scores sc where sc.academy_id = ac.id and sc.reviewed_at >= p_since) as avg_score_pct,
      (select round(100.0 * count(*) filter (where x.status = 'present') / nullif(count(*) filter (where x.status in ('present', 'absent')), 0), 1)
         from att x where x.academy_id = ac.id and x.marked_at >= p_since) as attendance_pct
    from public.academies ac
  ),
  months as (
    select generate_series(date_trunc('month', now() at time zone 'Asia/Kolkata') - interval '5 months', date_trunc('month', now() at time zone 'Asia/Kolkata'), interval '1 month') as m
  )
  select jsonb_build_object(
    'totals', jsonb_build_object(
      'academies', (select count(*) from public.academies),
      'academiesActive', (select count(*) from public.academies where status = 'active'),
      'students', (select count(*) from public.profiles where role = 'student'),
      'mentors', (select count(*) from public.profiles where role = 'mentor'),
      'academyAdmins', (select count(*) from public.profiles where role = 'academy_admin'),
      'batchesActive', (select count(*) from public.batches where status = 'active'),
      'newUsers', (select count(*) from public.profiles where created_at >= p_since)
    ),
    'activity', jsonb_build_object(
      'sessionsHeld', (select coalesce(sum(sessions_held), 0) from per_academy),
      'submissions', (select coalesce(sum(submissions), 0) from per_academy),
      'reviews', (select count(*) from scores where reviewed_at >= p_since),
      'avgScorePct', (select round(avg(pct), 1) from scores where reviewed_at >= p_since),
      'attendancePct', (select round(100.0 * count(*) filter (where status = 'present') / nullif(count(*) filter (where status in ('present', 'absent')), 0), 1) from att where marked_at >= p_since),
      'libraryCompletions', (select count(*) from public.content_progress where completed_at >= p_since)
    ),
    'academies', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id, 'name', name, 'status', status, 'students', students, 'mentors', mentors, 'batches', batches,
        'sessionsHeld', sessions_held, 'submissions', submissions, 'reviews', reviews,
        'avgScorePct', avg_score_pct, 'attendancePct', attendance_pct) order by name) from per_academy), '[]'::jsonb),
    'monthly', (select jsonb_agg(jsonb_build_object(
        'month', to_char(m, 'YYYY-MM'),
        'newUsers', (select count(*) from public.profiles p where date_trunc('month', p.created_at at time zone 'Asia/Kolkata') = m),
        'submissions', (select count(*) from public.assessment_attempts t where t.status = 'submitted' and date_trunc('month', t.submitted_at at time zone 'Asia/Kolkata') = m),
        'reviews', (select count(*) from scores sc where date_trunc('month', sc.reviewed_at at time zone 'Asia/Kolkata') = m)
      ) order by m) from months),
    'content', coalesce((select jsonb_agg(jsonb_build_object('category', category, 'published', n) order by category)
        from (select category, count(*) as n from public.contents where status = 'published' group by category) c), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;

revoke execute on function public.platform_analytics(timestamptz) from public, anon;
grant execute on function public.platform_analytics(timestamptz) to authenticated;

-- ===========================================================================
-- 0014_practice.sql
-- ===========================================================================
-- SSB Academy — T083b: practice banks and saved practice.
-- Run once in the Supabase SQL Editor, AFTER 0004–0013.
--
-- Design notes
--  * The question banks (TAT/WAT/SRT/SDT, OIR, PPDT, interview, conference)
--    move from code into practice_banks / practice_items. Only a super admin
--    edits them; items are deactivated, never deleted, so saved answers keep
--    their question. The seed at the end is the exact content the app shipped
--    with — platform content, not user data.
--  * practice_answers: one row per student per question for self-paced
--    practice (text or chosen option, self-review ticks, done).
--    practice_attempts: one row per timed test or mock interview/conference
--    run, idempotent on (student, client_key); MCQ is scored here, never by
--    the browser.
--  * Who reads answers (decided 2026-10-08): the student and the mentors of
--    their batch. Academy admins and super admins get counts only, through
--    practice_stats().

create type public.practice_item_kind as enum ('response', 'mcq');
create type public.practice_attempt_mode as enum ('test', 'mock');

create table public.practice_banks (
  slug text primary key,
  title text not null,
  item_kind public.practice_item_kind not null,
  created_at timestamptz not null default now(),
  constraint practice_banks_slug check (slug ~ '^[a-z0-9-]{2,40}$')
);

create table public.practice_items (
  id uuid primary key default gen_random_uuid(),
  bank_slug text not null references public.practice_banks(slug),
  -- Stable, human-readable id (e.g. 'tat-13'); app config refers to it.
  key text not null default ('item-' || substr(md5(random()::text), 1, 10)),
  position integer not null,  -- next free position when omitted (trigger)
  prompt text not null,
  options jsonb,
  correct_option_id text,
  guidance jsonb,
  active boolean not null default true,
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint practice_items_key unique (bank_slug, key),
  constraint practice_items_position unique (bank_slug, position) deferrable initially deferred,
  constraint practice_items_prompt check (char_length(btrim(prompt)) between 1 and 2000)
);

create index practice_items_bank_idx on public.practice_items (bank_slug, position);

-- Item shape per bank kind: MCQ needs 2–6 options and a correct one among
-- them; free-text items have neither. Guidance is {assesses, tips[]}.
create function public.check_practice_item()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  kind public.practice_item_kind;
begin
  select item_kind into kind from public.practice_banks where slug = new.bank_slug;
  if new.position is null then
    select coalesce(max(position), 0) + 1 into new.position from public.practice_items where bank_slug = new.bank_slug;
  end if;
  if kind = 'mcq' then
    if jsonb_typeof(new.options) is distinct from 'array'
      or jsonb_array_length(new.options) not between 2 and 6
      or exists (select 1 from jsonb_array_elements(new.options) o where jsonb_typeof(o->'id') <> 'string' or coalesce(btrim(o->>'label'), '') = '')
      or not exists (select 1 from jsonb_array_elements(new.options) o where o->>'id' = new.correct_option_id)
    then
      raise exception 'a multiple-choice item needs 2-6 labelled options and a correct option among them' using errcode = '23514';
    end if;
  elsif new.options is not null or new.correct_option_id is not null then
    raise exception 'a free-text item has no options' using errcode = '23514';
  end if;
  if new.guidance is not null and (
    jsonb_typeof(new.guidance) <> 'object'
    or coalesce(btrim(new.guidance->>'assesses'), '') = ''
    or jsonb_typeof(new.guidance->'tips') is distinct from 'array'
  ) then
    raise exception 'guidance needs what it assesses and a list of tips' using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger practice_items_check before insert or update on public.practice_items
  for each row execute function public.check_practice_item();

alter table public.practice_banks enable row level security;
alter table public.practice_items enable row level security;

create policy "practice_banks_read" on public.practice_banks for select using (auth.uid() is not null);
create policy "practice_items_read_active" on public.practice_items for select using (auth.uid() is not null and active);
create policy "practice_items_super_read" on public.practice_items for select using (public.is_super_admin());
create policy "practice_items_super_insert" on public.practice_items
  for insert with check (public.is_super_admin() and created_by = auth.uid());
create policy "practice_items_super_update" on public.practice_items
  for update using (public.is_super_admin()) with check (public.is_super_admin());
revoke delete on public.practice_items from authenticated, anon;

-- Reorder: swap an item with its neighbour, atomically (super admin only).
create function public.practice_move_item(p_item uuid, p_direction integer)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  me public.practice_items%rowtype;
  other public.practice_items%rowtype;
begin
  if not public.is_super_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into me from public.practice_items where id = p_item;
  if not found then
    raise exception 'no such item' using errcode = 'P0002';
  end if;
  if p_direction < 0 then
    select * into other from public.practice_items where bank_slug = me.bank_slug and position < me.position order by position desc limit 1;
  else
    select * into other from public.practice_items where bank_slug = me.bank_slug and position > me.position order by position asc limit 1;
  end if;
  if not found then
    return;
  end if;
  update public.practice_items
  set position = case when id = me.id then other.position else me.position end, updated_by = auth.uid()
  where id in (me.id, other.id);
end;
$$;

revoke execute on function public.practice_move_item(uuid, integer) from public, anon;
grant execute on function public.practice_move_item(uuid, integer) to authenticated;
revoke insert, update, delete on public.practice_banks from authenticated, anon;

-- ---------------------------------------------------------------------------
-- Saved practice
-- ---------------------------------------------------------------------------

-- The caller mentors a batch this student is in.
create function public.is_my_mentee(p_student uuid)
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (
    select 1 from public.batch_students bs
    join public.batch_mentors bm on bm.batch_id = bs.batch_id
    where bs.student_id = p_student and bm.mentor_id = auth.uid()
  )
$$;

create table public.practice_answers (
  student_id uuid not null references public.profiles(id) on delete cascade,
  item_id uuid not null references public.practice_items(id) on delete cascade,
  answer_text text,
  selected_option_id text,
  self_review text[] not null default '{}',
  done boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (student_id, item_id),
  constraint practice_answers_text check (answer_text is null or char_length(answer_text) <= 5000),
  constraint practice_answers_review check (cardinality(self_review) <= 20)
);

create index practice_answers_student_idx on public.practice_answers (student_id, updated_at desc);

create function public.touch_practice_answer()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger practice_answers_touch before insert or update on public.practice_answers
  for each row execute function public.touch_practice_answer();

create table public.practice_attempts (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  bank_slug text not null references public.practice_banks(slug),
  mode public.practice_attempt_mode not null,
  -- Generated by the browser once per run: a retried submit can't duplicate.
  client_key text not null,
  -- [{ "itemId": uuid, "prompt": text, "response": text } | { "itemId": uuid, "optionId": text }]
  answers jsonb not null,
  self_review jsonb not null default '{}'::jsonb,
  correct integer,
  total integer not null default 0,
  submitted_at timestamptz not null default now(),
  constraint practice_attempts_once unique (student_id, client_key),
  constraint practice_attempts_key check (char_length(client_key) between 8 and 80),
  constraint practice_attempts_answers check (jsonb_typeof(answers) = 'array' and jsonb_array_length(answers) <= 200),
  constraint practice_attempts_review check (jsonb_typeof(self_review) = 'object')
);

create index practice_attempts_student_idx on public.practice_attempts (student_id, submitted_at desc);

-- Answers must belong to the bank; MCQ is scored here. Text is capped.
create function public.score_practice_attempt()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  kind public.practice_item_kind;
begin
  -- Each answer is for a question in this bank; a mock run may also carry
  -- the student's own PIQ-based questions, which have a prompt and no itemId.
  if exists (
    select 1 from jsonb_array_elements(new.answers) a
    where char_length(coalesce(a->>'response', '')) > 5000
       or (a ? 'itemId' and not exists (select 1 from public.practice_items i where i.id::text = a->>'itemId' and i.bank_slug = new.bank_slug))
       or (not a ? 'itemId' and (new.mode <> 'mock' or char_length(coalesce(btrim(a->>'prompt'), '')) not between 1 and 500))
  ) then
    raise exception 'answers must be for questions in this bank' using errcode = '23514';
  end if;
  select item_kind into kind from public.practice_banks where slug = new.bank_slug;
  new.total := jsonb_array_length(new.answers);
  if kind = 'mcq' then
    select count(*) into new.correct
    from jsonb_array_elements(new.answers) a
    join public.practice_items i on i.id::text = a->>'itemId'
    where a->>'optionId' = i.correct_option_id;
  else
    new.correct := null;
  end if;
  new.submitted_at := now();
  return new;
end;
$$;

create trigger practice_attempts_score before insert on public.practice_attempts
  for each row execute function public.score_practice_attempt();

alter table public.practice_answers enable row level security;
alter table public.practice_attempts enable row level security;

create policy "practice_answers_own" on public.practice_answers
  for all
  using (student_id = auth.uid())
  with check (student_id = auth.uid() and public.current_user_role() = 'student');
create policy "practice_answers_mentor_read" on public.practice_answers
  for select using (public.is_my_mentee(student_id));

create policy "practice_attempts_own_read" on public.practice_attempts
  for select using (student_id = auth.uid());
create policy "practice_attempts_own_insert" on public.practice_attempts
  for insert with check (student_id = auth.uid() and public.current_user_role() = 'student');
create policy "practice_attempts_own_review" on public.practice_attempts
  for update using (student_id = auth.uid() and mode = 'mock') with check (student_id = auth.uid());
create policy "practice_attempts_mentor_read" on public.practice_attempts
  for select using (public.is_my_mentee(student_id));

-- After submit only the mock review ticks may change.
revoke update, delete on public.practice_attempts from authenticated, anon;
grant update (self_review) on public.practice_attempts to authenticated;

-- Counts only — for the student, their mentors, their academy's admins and
-- super admins. Anyone else gets nulls.
create function public.practice_stats(p_student uuid)
returns table (practice_done bigint, practice_tests bigint, last_practice_at timestamptz)
language plpgsql
stable
security definer set search_path = public
as $$
begin
  if not (
    p_student = auth.uid()
    or public.is_my_mentee(p_student)
    or exists (select 1 from public.profiles p where p.id = p_student and p.academy_id is not null and p.academy_id = public.current_admin_academy_id())
    or public.is_super_admin()
  ) then
    return query select null::bigint, null::bigint, null::timestamptz;
    return;
  end if;
  return query
    select
      (select count(*) from public.practice_answers a where a.student_id = p_student and a.done),
      (select count(*) from public.practice_attempts t where t.student_id = p_student),
      greatest(
        (select max(a.updated_at) from public.practice_answers a where a.student_id = p_student and a.done),
        (select max(t.submitted_at) from public.practice_attempts t where t.student_id = p_student)
      );
end;
$$;

revoke execute on function public.practice_stats(uuid) from public, anon;
grant execute on function public.practice_stats(uuid) to authenticated;

-- student_progress (0012) gains the practice counts (new columns at the end).
create or replace view public.student_progress
with (security_invoker = true) as
  select
    p.id as student_id,
    p.academy_id,
    bs.batch_id,
    (select count(*) from public.student_scores sc where sc.student_id = p.id) as reviewed_count,
    (select round(avg(sc.score_pct), 1) from public.student_scores sc where sc.student_id = p.id) as avg_score_pct,
    (select count(*) from public.session_attendance a where a.student_id = p.id and a.status = 'present') as sessions_present,
    (select count(*) from public.session_attendance a where a.student_id = p.id and a.status = 'absent') as sessions_absent,
    (select count(*) from public.content_progress c where c.student_id = p.id) as content_completed,
    (select max(t.submitted_at) from public.assessment_attempts t where t.student_id = p.id and t.status = 'submitted') as last_submission_at,
    ps.practice_done,
    ps.practice_tests,
    ps.last_practice_at
  from public.profiles p
  left join public.batch_students bs on bs.student_id = p.id
  left join lateral public.practice_stats(p.id) ps on true
  where p.role = 'student';

grant select on public.practice_banks, public.practice_items, public.practice_answers, public.practice_attempts to authenticated;

