-- ===========================================================================
-- 0015_auth_trusted_role_sync.sql
-- ===========================================================================
-- SSB Academy — T090: apply server-granted roles that Supabase Auth writes
-- AFTER the auth.users INSERT. Run once in the Supabase SQL Editor, AFTER 0014.
--
-- Why
--  * handle_new_user (0005/0007) runs AFTER INSERT on auth.users. Verified on
--    a local stack (GoTrue v2): auth.admin.createUser() inserts the row first
--    and writes app_metadata.role in a later UPDATE, and inviteUserByEmail()
--    sets invited_at in a later UPDATE. The insert trigger saw neither, so
--    every invited mentor/student and every admin-created account became a
--    student with no academy.
--
-- What
--  * One AFTER UPDATE trigger that applies the trusted role at exactly two
--    transitions, both of which only Supabase Auth / the service role can cause:
--      1. raw_app_meta_data->>'role' changes (app_metadata is service-role-only)
--      2. invited_at goes from null to set (only inviteUserByEmail does this);
--         the role/academy then come from the invite's metadata, read at that
--         moment only — later user_metadata edits by the user change nothing.
--  * Browser signups are unaffected: user_metadata alone never grants a role.

create function public.apply_trusted_role()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  app_role text := new.raw_app_meta_data->>'role';
  meta_role text := new.raw_user_meta_data->>'role';
  target_role public.user_role;
  target_academy uuid;
  current_academy uuid;
begin
  if app_role in ('student', 'mentor', 'academy_admin', 'super_admin')
     and app_role is distinct from old.raw_app_meta_data->>'role' then
    target_role := app_role::public.user_role;
    target_academy := nullif(new.raw_app_meta_data->>'academy_id', '')::uuid;
  elsif meta_role in ('mentor', 'student') and old.invited_at is null and new.invited_at is not null then
    target_role := meta_role::public.user_role;
    target_academy := nullif(new.raw_user_meta_data->>'academy_id', '')::uuid;
  else
    return new;
  end if;

  select academy_id into current_academy from public.profiles where id = new.id;
  if not found then
    return new;
  end if;

  target_academy := coalesce(target_academy, current_academy);
  if target_role = 'academy_admin' and target_academy is null then
    insert into public.academies (name, owner_id)
    values (coalesce(nullif(btrim(new.raw_user_meta_data->>'academy_name'), ''), 'My Academy'), new.id)
    returning id into target_academy;
  end if;

  -- auth.uid() is null in Supabase Auth's own session, so the 0005/0007
  -- profile guard treats this as a trusted change; it also creates the
  -- role-specific profile row when the role changes.
  update public.profiles
  set role = target_role, academy_id = target_academy
  where id = new.id;

  return new;
end;
$$;

revoke execute on function public.apply_trusted_role() from public, anon, authenticated;

create trigger on_auth_user_trusted_role
  after update of raw_app_meta_data, invited_at on auth.users
  for each row execute function public.apply_trusted_role();

-- ===========================================================================
-- 0016_demo_requests.sql
-- ===========================================================================
-- SSB Academy — demo requests from the public landing page.
-- Run once in the Supabase SQL Editor, AFTER 0015.
--
-- ADDITIVE: one new table, no change to any existing object.
--  * Anyone (signed in or not) may INSERT a request; nobody but a super admin
--    may read one. There is no update or delete path through the API.
--  * Shape and length limits are enforced here as well as in the app
--    (lib/server/demo-requests/validation.ts), so a direct API call can't
--    store anything the form couldn't.

create table public.demo_requests (
  id uuid primary key default gen_random_uuid(),
  full_name text not null,
  email text not null,
  phone text,
  organisation text,
  interest text not null,
  message text,
  created_at timestamptz not null default now(),
  constraint demo_requests_full_name_length check (char_length(btrim(full_name)) between 2 and 80),
  constraint demo_requests_email_shape check (char_length(email) <= 254 and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  constraint demo_requests_phone_length check (phone is null or char_length(phone) between 7 and 20),
  constraint demo_requests_organisation_length check (organisation is null or char_length(organisation) <= 120),
  constraint demo_requests_interest check (interest in ('student', 'mentor', 'academy')),
  constraint demo_requests_message_length check (message is null or char_length(message) <= 1000)
);

create index demo_requests_created_idx on public.demo_requests (created_at desc);

alter table public.demo_requests enable row level security;

create policy "demo_requests_insert_anyone" on public.demo_requests
  for insert to anon, authenticated with check (true);
create policy "demo_requests_select_super_admin" on public.demo_requests
  for select using (public.is_super_admin());

revoke all on public.demo_requests from anon, authenticated;
grant insert (full_name, email, phone, organisation, interest, message) on public.demo_requests to anon, authenticated;
grant select on public.demo_requests to authenticated;

notify pgrst, 'reload schema';

-- ===========================================================================
-- 0017_ai_jobs.sql
-- ===========================================================================
-- SSB Academy — T101: AI foundation (job queue, evaluations, usage).
-- Run once in the Supabase SQL Editor, AFTER 0016.
--
-- Design notes (specs.md §0.1, PRD §11.7/§12)
--  * AI work never runs inside a web request. The app (or a trigger) enqueues
--    a job; the separate worker service (worker/) claims it, calls the model,
--    validates the output and writes the evaluation. The student's answer is
--    already stored before the job exists, so an AI failure never loses input.
--  * The job snapshots its input (question + answer) so an evaluation is
--    reproducible and tied to the rubric version that produced it.
--  * Clients can read their own (student) or their mentee's (mentor) jobs and
--    evaluations; nobody writes them through the API. The worker connects as
--    the database owner and uses the functions below.
--  * Every evaluation carries the label "AI-generated practice evaluation".

create type public.ai_job_status as enum ('queued', 'running', 'succeeded', 'failed', 'dead');
create type public.ai_rating as enum ('needs_attention', 'developing', 'strong');
create type public.ai_confidence as enum ('low', 'medium', 'high');

create table public.ai_jobs (
  id uuid primary key default gen_random_uuid(),
  -- What is being evaluated, e.g. ('practice_attempt', <id>).
  subject_type text not null,
  subject_id uuid not null,
  student_id uuid not null references public.profiles(id) on delete cascade,
  rubric_id text not null,
  rubric_version integer not null,
  -- {"items": [{"prompt": text, "response": text}], "context": {...}}
  input jsonb not null,
  status public.ai_job_status not null default 'queued',
  attempts integer not null default 0,
  max_attempts integer not null default 3,
  run_after timestamptz not null default now(),
  locked_at timestamptz,
  locked_by text,
  last_error_code text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ai_jobs_subject_type check (subject_type ~ '^[a-z_]{2,40}$'),
  constraint ai_jobs_rubric check (rubric_id ~ '^[a-z0-9-]{2,60}$' and rubric_version > 0),
  constraint ai_jobs_input check (jsonb_typeof(input) = 'object' and jsonb_typeof(input->'items') = 'array'),
  constraint ai_jobs_attempts check (attempts >= 0 and max_attempts between 1 and 10),
  -- One evaluation per subject per rubric version: re-enqueueing is a no-op.
  constraint ai_jobs_once unique (subject_type, subject_id, rubric_id, rubric_version)
);

create index ai_jobs_claim_idx on public.ai_jobs (run_after) where status = 'queued';
create index ai_jobs_student_idx on public.ai_jobs (student_id, created_at desc);

create table public.ai_evaluations (
  id uuid primary key default gen_random_uuid(),
  job_id uuid not null unique references public.ai_jobs(id) on delete cascade,
  subject_type text not null,
  subject_id uuid not null,
  student_id uuid not null references public.profiles(id) on delete cascade,
  rubric_id text not null,
  rubric_version integer not null,
  model text not null,
  label text not null default 'AI-generated practice evaluation',
  -- [{"dimension": id, "rating": ai_rating, "confidence": ai_confidence, "evidence": [quote], "note": text}]
  dimensions jsonb not null,
  -- {"observation", "evidence", "impact", "improvement_action", "recommended_practice"}
  feedback jsonb not null,
  overall_confidence public.ai_confidence not null,
  created_at timestamptz not null default now(),
  constraint ai_evaluations_label check (label = 'AI-generated practice evaluation'),
  constraint ai_evaluations_dimensions check (jsonb_typeof(dimensions) = 'array' and jsonb_array_length(dimensions) between 1 and 12),
  constraint ai_evaluations_feedback check (
    jsonb_typeof(feedback) = 'object'
    and feedback ?& array['observation', 'evidence', 'impact', 'improvement_action', 'recommended_practice']
  )
);

create index ai_evaluations_subject_idx on public.ai_evaluations (subject_type, subject_id);
create index ai_evaluations_student_idx on public.ai_evaluations (student_id, created_at desc);

-- Per model call: cost and latency telemetry (PRD §12.9 "log telemetry").
create table public.ai_usage (
  id bigint generated always as identity primary key,
  job_id uuid references public.ai_jobs(id) on delete set null,
  model text not null,
  input_tokens integer not null default 0,
  output_tokens integer not null default 0,
  cache_read_tokens integer not null default 0,
  cache_write_tokens integer not null default 0,
  cost_micro_usd bigint,
  latency_ms integer not null,
  outcome text not null,
  created_at timestamptz not null default now(),
  constraint ai_usage_outcome check (outcome ~ '^[a-z_]{2,40}$')
);

create index ai_usage_created_idx on public.ai_usage (created_at desc);

alter table public.ai_jobs enable row level security;
alter table public.ai_evaluations enable row level security;
alter table public.ai_usage enable row level security;

-- Reads only. The student sees their own; their batch mentors see a mentee's.
create policy "ai_jobs_own_read" on public.ai_jobs for select using (student_id = auth.uid());
create policy "ai_jobs_mentor_read" on public.ai_jobs for select using (public.is_my_mentee(student_id));
create policy "ai_evaluations_own_read" on public.ai_evaluations for select using (student_id = auth.uid());
create policy "ai_evaluations_mentor_read" on public.ai_evaluations for select using (public.is_my_mentee(student_id));
create policy "ai_usage_super_read" on public.ai_usage for select using (public.is_super_admin());

revoke insert, update, delete on public.ai_jobs, public.ai_evaluations, public.ai_usage from authenticated, anon;
grant select on public.ai_jobs, public.ai_evaluations, public.ai_usage to authenticated;

-- ---------------------------------------------------------------------------
-- Queue functions (internal: not callable through the API)
-- ---------------------------------------------------------------------------

-- Enqueue an evaluation. Idempotent per (subject, rubric version).
create function public.enqueue_ai_evaluation(
  p_subject_type text, p_subject_id uuid, p_student_id uuid,
  p_rubric_id text, p_rubric_version integer, p_input jsonb
)
returns uuid
language plpgsql
security definer set search_path = public
as $$
declare
  job uuid;
begin
  insert into public.ai_jobs (subject_type, subject_id, student_id, rubric_id, rubric_version, input)
  values (p_subject_type, p_subject_id, p_student_id, p_rubric_id, p_rubric_version, p_input)
  on conflict (subject_type, subject_id, rubric_id, rubric_version) do nothing
  returning id into job;
  if job is null then
    select id into job from public.ai_jobs
    where subject_type = p_subject_type and subject_id = p_subject_id
      and rubric_id = p_rubric_id and rubric_version = p_rubric_version;
  end if;
  return job;
end;
$$;

-- Claim up to p_limit due jobs. A job left 'running' for 10 minutes (a worker
-- that crashed) is claimable again; its attempt still counts.
create function public.ai_claim_jobs(p_worker text, p_limit integer)
returns setof public.ai_jobs
language plpgsql
security definer set search_path = public
as $$
begin
  return query
  update public.ai_jobs j
  set status = 'running', locked_at = now(), locked_by = p_worker,
      attempts = j.attempts + 1, updated_at = now()
  where j.id in (
    select id from public.ai_jobs
    where (status = 'queued' and run_after <= now())
       or (status = 'running' and locked_at < now() - interval '10 minutes')
    order by run_after
    limit greatest(1, least(p_limit, 20))
    for update skip locked
  )
  returning j.*;
end;
$$;

-- Success: store the evaluation and close the job, atomically.
create function public.ai_complete_job(
  p_job uuid, p_worker text, p_model text, p_dimensions jsonb, p_feedback jsonb, p_confidence public.ai_confidence
)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  j public.ai_jobs%rowtype;
begin
  select * into j from public.ai_jobs where id = p_job for update;
  if not found or j.status <> 'running' or j.locked_by is distinct from p_worker then
    raise exception 'job % is not held by this worker', p_job using errcode = '55000';
  end if;
  insert into public.ai_evaluations (job_id, subject_type, subject_id, student_id, rubric_id, rubric_version, model, dimensions, feedback, overall_confidence)
  values (j.id, j.subject_type, j.subject_id, j.student_id, j.rubric_id, j.rubric_version, p_model, p_dimensions, p_feedback, p_confidence);
  update public.ai_jobs
  set status = 'succeeded', locked_at = null, locked_by = null, last_error_code = null, updated_at = now()
  where id = p_job;
end;
$$;

-- Failure: retry later with exponential backoff, or give up ('dead') when the
-- error can't be fixed by retrying or attempts are used up.
create function public.ai_fail_job(p_job uuid, p_worker text, p_error_code text, p_retryable boolean)
returns public.ai_job_status
language plpgsql
security definer set search_path = public
as $$
declare
  j public.ai_jobs%rowtype;
  next_status public.ai_job_status;
begin
  select * into j from public.ai_jobs where id = p_job for update;
  if not found or j.status <> 'running' or j.locked_by is distinct from p_worker then
    raise exception 'job % is not held by this worker', p_job using errcode = '55000';
  end if;
  next_status := case when p_retryable and j.attempts < j.max_attempts then 'queued' else 'dead' end;
  update public.ai_jobs
  set status = next_status,
      run_after = case when next_status = 'queued' then now() + make_interval(secs => 30 * power(2, j.attempts - 1)) else run_after end,
      locked_at = null, locked_by = null, last_error_code = left(p_error_code, 60), updated_at = now()
  where id = p_job;
  return next_status;
end;
$$;

create function public.ai_log_usage(
  p_job uuid, p_model text, p_input integer, p_output integer, p_cache_read integer, p_cache_write integer,
  p_cost_micro_usd bigint, p_latency_ms integer, p_outcome text
)
returns void
language sql
security definer set search_path = public
as $$
  insert into public.ai_usage (job_id, model, input_tokens, output_tokens, cache_read_tokens, cache_write_tokens, cost_micro_usd, latency_ms, outcome)
  values (p_job, p_model, p_input, p_output, p_cache_read, p_cache_write, p_cost_micro_usd, p_latency_ms, p_outcome);
$$;

revoke execute on function public.enqueue_ai_evaluation(text, uuid, uuid, text, integer, jsonb) from public, anon, authenticated;
revoke execute on function public.ai_claim_jobs(text, integer) from public, anon, authenticated;
revoke execute on function public.ai_complete_job(uuid, text, text, jsonb, jsonb, public.ai_confidence) from public, anon, authenticated;
revoke execute on function public.ai_fail_job(uuid, text, text, boolean) from public, anon, authenticated;
revoke execute on function public.ai_log_usage(uuid, text, integer, integer, integer, integer, bigint, integer, text) from public, anon, authenticated;

-- ===========================================================================
-- 0018_psychology_feedback.sql
-- ===========================================================================
-- SSB Academy — T102: AI feedback on psychology practice (TAT/WAT/SRT/SD).
-- Run once in the Supabase SQL Editor, AFTER 0017.
--
--  * Submitting a timed psychology test (practice_attempts, mode 'test', bank
--    tat/wat/srt/sdt) enqueues one AI evaluation in the same transaction, using
--    the rubric for that test (worker/src/rubrics/psychology.ts). The answers
--    are already stored, so the student loses nothing if the AI fails.
--  * When the evaluation is stored, the student is notified.
--  * Timers are configurable per bank (FR-PSY-01); the app falls back to its
--    standard timings when a bank has none.

alter type public.notification_kind add value if not exists 'ai_feedback_ready';

-- {"mode": "carousel", "stimulusSeconds"?: int, "responseSeconds": int} or
-- {"mode": "budget", "totalSeconds": int}
alter table public.practice_banks add column timing jsonb;
alter table public.practice_banks add constraint practice_banks_timing check (
  timing is null
  or (timing->>'mode' = 'carousel'
      and (timing->>'responseSeconds')::int between 5 and 900
      and coalesce((timing->>'stimulusSeconds')::int, 0) between 0 and 120)
  or (timing->>'mode' = 'budget' and (timing->>'totalSeconds')::int between 60 and 7200)
);

-- Super admins set timers (banks are otherwise not writable through the API).
create function public.set_practice_bank_timing(p_slug text, p_timing jsonb)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  if not public.is_super_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.practice_banks set timing = p_timing where slug = p_slug;
  if not found then
    raise exception 'no such bank' using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function public.set_practice_bank_timing(text, jsonb) from public, anon;
grant execute on function public.set_practice_bank_timing(text, jsonb) to authenticated;

create function public.enqueue_psychology_feedback()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  items jsonb;
begin
  if new.mode <> 'test' or new.bank_slug not in ('tat', 'wat', 'srt', 'sdt') then
    return new;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('prompt', i.prompt, 'response', coalesce(a.value->>'response', '')) order by i.position), '[]'::jsonb)
  into items
  from jsonb_array_elements(new.answers) a
  join public.practice_items i on i.id::text = a.value->>'itemId';
  -- Nothing written means nothing to evaluate.
  if not exists (select 1 from jsonb_array_elements(items) x where btrim(x->>'response') <> '') then
    return new;
  end if;
  perform public.enqueue_ai_evaluation('practice_attempt', new.id, new.student_id, 'psychology-' || new.bank_slug, 1,
    jsonb_build_object('items', items, 'context', jsonb_build_object('test', new.bank_slug)));
  return new;
end;
$$;

create trigger practice_attempts_ai_feedback after insert on public.practice_attempts
  for each row execute function public.enqueue_psychology_feedback();

create function public.notify_ai_feedback()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  if new.subject_type = 'practice_attempt' and new.rubric_id like 'psychology-%' then
    perform public.notify(new.student_id, 'ai_feedback_ready', 'Your practice feedback is ready',
      upper(replace(new.rubric_id, 'psychology-', '')) || ' practice', '/student/practice/psychology/results/' || new.subject_id, new.id);
  end if;
  return new;
end;
$$;

create trigger ai_evaluations_notify after insert on public.ai_evaluations
  for each row execute function public.notify_ai_feedback();

-- ===========================================================================
-- 0019_ai_interview.sql
-- ===========================================================================
-- SSB Academy — T103: AI interview with dynamic follow-ups (PRD §11.1, FR-INT-01/02).
-- Run once in the Supabase SQL Editor, AFTER 0018.
--
--  * A session is a sequence of turns (question → answer). After each answer
--    the worker writes the next question, chosen from what the student just
--    said (clarification, evidence, depth, consistency, reflection) or a new
--    topic. After the last answer it writes structured feedback (rubric
--    'interview' v1), stored as an ordinary ai_evaluation.
--  * The AI never blocks practice: if a question can't be generated, the next
--    question comes from the interview bank instead — automatically when the
--    job gives up, or when the student chooses "Skip to the next question".
--  * Students write only through the functions below; reads follow the usual
--    rule (the student, and the mentors of their batch).
--  * New AI jobs wake the worker immediately (pg_notify), so a follow-up
--    doesn't wait for the next poll.

create type public.interview_mode as enum ('guided', 'topic', 'mock');
create type public.interview_status as enum ('active', 'completed');
create type public.interview_turn_kind as enum ('opening', 'follow_up', 'new_topic', 'bank');
create type public.interview_follow_up as enum ('clarification', 'evidence', 'depth', 'consistency', 'reflection');

-- Topic practice: the student picks one; the opening question comes from here.
create table public.interview_topics (
  slug text primary key,
  title text not null,
  opening_question text not null,
  position integer not null,
  constraint interview_topics_slug check (slug ~ '^[a-z0-9-]{2,40}$')
);

insert into public.interview_topics (slug, title, opening_question, position) values
  ('motivation', 'Why the Armed Forces', 'Why do you want to join the Armed Forces?', 1),
  ('family', 'Family and background', 'Tell us about your family and how you grew up.', 2),
  ('education', 'Education', 'Tell us about your studies so far and what you enjoyed most.', 3),
  ('responsibility', 'Responsibilities and leadership', 'Tell us about a responsibility you have taken on recently.', 4),
  ('hobbies', 'Hobbies and sports', 'What do you do in your free time, and how did you get into it?', 5),
  ('friends', 'Friends and teamwork', 'Tell us about your friends and what you do together.', 6),
  ('current-affairs', 'Current affairs', 'Which recent event in India or the world have you followed closely, and why?', 7);

alter table public.interview_topics enable row level security;
create policy "interview_topics_read" on public.interview_topics for select using (auth.uid() is not null);
revoke insert, update, delete on public.interview_topics from authenticated, anon;
grant select on public.interview_topics to authenticated;

create table public.interview_sessions (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  mode public.interview_mode not null,
  topic_slug text references public.interview_topics(slug),
  max_questions integer not null,
  -- Optional PIQ details the student chose to share for this session only.
  context jsonb not null default '{}'::jsonb,
  status public.interview_status not null default 'active',
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  constraint interview_sessions_topic check ((mode = 'topic') = (topic_slug is not null)),
  constraint interview_sessions_max check (max_questions between 3 and 12),
  constraint interview_sessions_context check (jsonb_typeof(context) = 'object' and pg_column_size(context) < 8000)
);

create index interview_sessions_student_idx on public.interview_sessions (student_id, created_at desc);

create table public.interview_turns (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.interview_sessions(id) on delete cascade,
  seq integer not null,
  question text not null,
  kind public.interview_turn_kind not null,
  follow_up_type public.interview_follow_up,
  answer text,
  answered_at timestamptz,
  created_at timestamptz not null default now(),
  constraint interview_turns_seq unique (session_id, seq),
  constraint interview_turns_question check (char_length(btrim(question)) between 5 and 400),
  constraint interview_turns_answer check (answer is null or char_length(answer) <= 3000),
  constraint interview_turns_follow_up check ((kind = 'follow_up') = (follow_up_type is not null))
);

alter table public.interview_sessions enable row level security;
alter table public.interview_turns enable row level security;

create policy "interview_sessions_own_read" on public.interview_sessions for select using (student_id = auth.uid());
create policy "interview_sessions_mentor_read" on public.interview_sessions for select using (public.is_my_mentee(student_id));
create policy "interview_turns_read" on public.interview_turns for select using (
  exists (select 1 from public.interview_sessions s where s.id = session_id and (s.student_id = auth.uid() or public.is_my_mentee(s.student_id)))
);
revoke insert, update, delete on public.interview_sessions, public.interview_turns from authenticated, anon;
grant select on public.interview_sessions, public.interview_turns to authenticated;

-- AI jobs gain a kind: 'evaluation' (0017) or 'interview_question'.
alter table public.ai_jobs add column kind text not null default 'evaluation';
alter table public.ai_jobs add constraint ai_jobs_kind check (kind in ('evaluation', 'interview_question'));

-- Wake the worker as soon as a job is queued.
create function public.ai_jobs_wake()
returns trigger
language plpgsql
as $$
begin
  perform pg_notify('ai_jobs', new.id::text);
  return new;
end;
$$;

create trigger ai_jobs_wake after insert on public.ai_jobs
  for each row execute function public.ai_jobs_wake();

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

-- The transcript the worker sees: every turn so far, plus the session settings.
create function public.interview_job_input(p_session uuid)
returns jsonb
language sql
stable
security definer set search_path = public
as $$
  select jsonb_build_object(
    'session', jsonb_build_object('mode', s.mode, 'topic', t.title, 'max_questions', s.max_questions, 'context', s.context),
    'items', coalesce((select jsonb_agg(jsonb_build_object('prompt', it.question, 'response', coalesce(it.answer, ''), 'kind', it.kind) order by it.seq)
                       from public.interview_turns it where it.session_id = s.id), '[]'::jsonb)
  )
  from public.interview_sessions s
  left join public.interview_topics t on t.slug = s.topic_slug
  where s.id = p_session;
$$;

-- Next question from the bank that this session hasn't asked yet.
create function public.interview_bank_question(p_session uuid)
returns text
language sql
stable
security definer set search_path = public
as $$
  select i.prompt from public.practice_items i
  where i.bank_slug = 'interview' and i.active
    and not exists (select 1 from public.interview_turns t where t.session_id = p_session and t.question = i.prompt)
  order by i.position
  limit 1;
$$;

-- Append the next question (worker or bank), or finish the session when the
-- question budget is used up. Idempotent: only when the last turn is answered.
create function public.interview_append_question(p_session uuid, p_question text, p_kind public.interview_turn_kind, p_follow_up public.interview_follow_up)
returns boolean
language plpgsql
security definer set search_path = public
as $$
declare
  s public.interview_sessions%rowtype;
  last public.interview_turns%rowtype;
begin
  select * into s from public.interview_sessions where id = p_session for update;
  if not found or s.status <> 'active' then
    return false;
  end if;
  select * into last from public.interview_turns where session_id = p_session order by seq desc limit 1;
  if last.answered_at is null or last.seq >= s.max_questions then
    return false;
  end if;
  insert into public.interview_turns (session_id, seq, question, kind, follow_up_type)
  values (p_session, last.seq + 1, btrim(p_question), p_kind, case when p_kind = 'follow_up' then p_follow_up end);
  return true;
end;
$$;

-- ---------------------------------------------------------------------------
-- Student actions
-- ---------------------------------------------------------------------------

create function public.start_interview_session(p_mode public.interview_mode, p_topic text, p_context jsonb)
returns uuid
language plpgsql
security definer set search_path = public
as $$
declare
  me uuid := auth.uid();
  sid uuid;
  opening text;
begin
  if me is null or public.current_user_role() <> 'student' then
    raise exception 'only a student can start an interview' using errcode = '42501';
  end if;
  if p_mode = 'topic' then
    select opening_question into opening from public.interview_topics where slug = p_topic;
    if opening is null then
      raise exception 'choose a topic' using errcode = '23514';
    end if;
  else
    -- "Tell us about yourself" opens guided and mock interviews.
    select prompt into opening from public.practice_items where bank_slug = 'interview' and key = 'int-1' and active;
    opening := coalesce(opening, (select prompt from public.practice_items where bank_slug = 'interview' and active order by position limit 1));
  end if;
  insert into public.interview_sessions (student_id, mode, topic_slug, max_questions, context)
  values (me, p_mode, case when p_mode = 'topic' then p_topic end, case p_mode when 'mock' then 8 else 5 end, coalesce(p_context, '{}'::jsonb))
  returning id into sid;
  insert into public.interview_turns (session_id, seq, question, kind) values (sid, 1, opening, 'opening');
  return sid;
end;
$$;

-- Save the answer to the current question, then queue the next question —
-- or, after the last one, the feedback.
create function public.answer_interview_turn(p_turn uuid, p_answer text)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  t public.interview_turns%rowtype;
  s public.interview_sessions%rowtype;
begin
  select * into t from public.interview_turns where id = p_turn for update;
  select * into s from public.interview_sessions where id = t.session_id for update;
  if not found or s.student_id is distinct from auth.uid() then
    raise exception 'not your interview' using errcode = '42501';
  end if;
  if s.status <> 'active' or t.answered_at is not null
     or t.seq <> (select max(seq) from public.interview_turns where session_id = s.id) then
    raise exception 'this question is no longer open' using errcode = '23514';
  end if;
  update public.interview_turns set answer = left(coalesce(p_answer, ''), 3000), answered_at = now() where id = p_turn;

  if t.seq >= s.max_questions then
    update public.interview_sessions set status = 'completed', completed_at = now() where id = s.id;
    perform public.enqueue_ai_evaluation('interview_session', s.id, s.student_id, 'interview', 1, public.interview_job_input(s.id));
  else
    insert into public.ai_jobs (kind, subject_type, subject_id, student_id, rubric_id, rubric_version, input, max_attempts)
    values ('interview_question', 'interview_turn', t.id, s.student_id, 'interview-question', 1, public.interview_job_input(s.id), 2)
    on conflict (subject_type, subject_id, rubric_id, rubric_version) do nothing;
  end if;
end;
$$;

-- "Skip to the next question" when the AI is slow: take one from the bank.
create function public.skip_interview_wait(p_session uuid)
returns boolean
language plpgsql
security definer set search_path = public
as $$
declare
  s public.interview_sessions%rowtype;
  q text;
begin
  select * into s from public.interview_sessions where id = p_session;
  if not found or s.student_id is distinct from auth.uid() then
    raise exception 'not your interview' using errcode = '42501';
  end if;
  q := public.interview_bank_question(p_session);
  if q is null then
    return false;
  end if;
  return public.interview_append_question(p_session, q, 'bank', null);
end;
$$;

-- ---------------------------------------------------------------------------
-- Worker side (internal)
-- ---------------------------------------------------------------------------

create function public.ai_complete_interview_question(p_job uuid, p_worker text, p_question text, p_kind public.interview_turn_kind, p_follow_up public.interview_follow_up)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  j public.ai_jobs%rowtype;
  sid uuid;
begin
  select * into j from public.ai_jobs where id = p_job for update;
  if not found or j.status <> 'running' or j.locked_by is distinct from p_worker or j.kind <> 'interview_question' then
    raise exception 'job % is not held by this worker', p_job using errcode = '55000';
  end if;
  select session_id into sid from public.interview_turns where id = j.subject_id;
  -- Only if the answer this question follows is still the latest turn: if the
  -- student skipped ahead in the meantime, the follow-up is stale and dropped.
  if (select id from public.interview_turns where session_id = sid order by seq desc limit 1) = j.subject_id then
    perform public.interview_append_question(sid, p_question, p_kind, p_follow_up);
  end if;
  update public.ai_jobs set status = 'succeeded', locked_at = null, locked_by = null, last_error_code = null, updated_at = now() where id = p_job;
end;
$$;

-- When a question job gives up, continue from the bank so practice never stops.
create function public.interview_fallback_on_dead()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  sid uuid;
  q text;
begin
  if new.kind = 'interview_question' and new.status = 'dead' and old.status <> 'dead' then
    select session_id into sid from public.interview_turns where id = new.subject_id;
    q := public.interview_bank_question(sid);
    if q is not null then
      perform public.interview_append_question(sid, q, 'bank', null);
    end if;
  end if;
  return new;
end;
$$;

create trigger ai_jobs_interview_fallback after update of status on public.ai_jobs
  for each row execute function public.interview_fallback_on_dead();

-- Feedback ready → notify, linking to the interview.
create or replace function public.notify_ai_feedback()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  if new.subject_type = 'practice_attempt' and new.rubric_id like 'psychology-%' then
    perform public.notify(new.student_id, 'ai_feedback_ready', 'Your practice feedback is ready',
      upper(replace(new.rubric_id, 'psychology-', '')) || ' practice', '/student/practice/psychology/results/' || new.subject_id, new.id);
  elsif new.subject_type = 'interview_session' then
    perform public.notify(new.student_id, 'ai_feedback_ready', 'Your interview feedback is ready',
      'AI interview practice', '/student/practice/interview/ai/' || new.subject_id, new.id);
  end if;
  return new;
end;
$$;

revoke execute on function public.interview_job_input(uuid) from public, anon, authenticated;
revoke execute on function public.interview_bank_question(uuid) from public, anon, authenticated;
revoke execute on function public.interview_append_question(uuid, text, public.interview_turn_kind, public.interview_follow_up) from public, anon, authenticated;
revoke execute on function public.ai_complete_interview_question(uuid, text, text, public.interview_turn_kind, public.interview_follow_up) from public, anon, authenticated;
revoke execute on function public.start_interview_session(public.interview_mode, text, jsonb) from public, anon;
revoke execute on function public.answer_interview_turn(uuid, text) from public, anon;
revoke execute on function public.skip_interview_wait(uuid) from public, anon;
grant execute on function public.start_interview_session(public.interview_mode, text, jsonb) to authenticated;
grant execute on function public.answer_interview_turn(uuid, text) to authenticated;
grant execute on function public.skip_interview_wait(uuid) to authenticated;

-- ===========================================================================
-- 0020_readiness_signals.sql
-- ===========================================================================
-- SSB Academy — T104: readiness profile signals (PRD §11.8, FR-DASH-02).
-- Run once in the Supabase SQL Editor, AFTER 0019.
--
-- One function gathers, for one student, the numbers the readiness profile is
-- built from: mentor review scores by category, AI practice-evaluation ratings
-- by rubric dimension, practice activity, Library reads, attendance and active
-- days. It returns counts and averages only — never answer or feedback text —
-- so the same numbers can be shown to the student, their mentors, their
-- academy's admins (states only, in the app) and super admins. The states are
-- computed in the app (lib/server/readiness/compute.ts) by fixed rules, never
-- by AI (PRD §5.3: deterministic logic for progress math).

create function public.readiness_signals(p_student uuid)
returns jsonb
language plpgsql
stable
security definer set search_path = public
as $$
declare
  result jsonb;
  since_28 timestamptz := now() - interval '28 days';
  since_7 timestamptz := now() - interval '7 days';
begin
  if not (
    p_student = auth.uid()
    or public.is_my_mentee(p_student)
    or exists (select 1 from public.profiles p where p.id = p_student and p.role = 'student' and p.academy_id is not null and p.academy_id = public.current_admin_academy_id())
    or public.is_super_admin()
  ) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  with
  scores as (
    select category::text as category, score_pct, row_number() over (partition by category order by reviewed_at desc) as rn
    from public.student_scores where student_id = p_student
  ),
  evals as (
    select e.rubric_id, e.dimensions, row_number() over (partition by e.rubric_id order by e.created_at desc) as rn
    from public.ai_evaluations e
    where e.student_id = p_student and e.created_at >= now() - interval '90 days'
  ),
  ai_rows as (
    select ev.rubric_id, d->>'dimension' as dimension, d->>'rating' as rating, d->>'confidence' as confidence, (ev.rn <= 2) as recent
    from evals ev, jsonb_array_elements(ev.dimensions) d
  ),
  activity as (
    select (updated_at at time zone 'Asia/Kolkata')::date as day from public.practice_answers where student_id = p_student and done and updated_at >= since_28
    union select (submitted_at at time zone 'Asia/Kolkata')::date from public.practice_attempts where student_id = p_student and submitted_at >= since_28
    union select (submitted_at at time zone 'Asia/Kolkata')::date from public.assessment_attempts where student_id = p_student and status = 'submitted' and submitted_at >= since_28
    union select (completed_at at time zone 'Asia/Kolkata')::date from public.content_progress where student_id = p_student and completed_at >= since_28
    union select (s.starts_at at time zone 'Asia/Kolkata')::date from public.session_attendance a join public.sessions s on s.id = a.session_id where a.student_id = p_student and a.status = 'present' and s.starts_at >= since_28
  )
  select jsonb_build_object(
    'account_created_at', (select created_at from public.profiles where id = p_student),
    'mentor', coalesce((select jsonb_agg(jsonb_build_object(
        'category', category, 'n', n, 'avg_pct', avg_pct, 'recent_avg', recent_avg, 'previous_avg', previous_avg))
      from (select category, count(*) as n, round(avg(score_pct), 1) as avg_pct,
                   round(avg(score_pct) filter (where rn <= 3), 1) as recent_avg,
                   round(avg(score_pct) filter (where rn between 4 and 6), 1) as previous_avg
            from scores group by category) m), '[]'::jsonb),
    'ai', coalesce((select jsonb_agg(jsonb_build_object('rubric_id', rubric_id, 'dimension', dimension, 'rating', rating, 'confidence', confidence, 'recent', recent, 'n', n))
      from (select rubric_id, dimension, rating, confidence, recent, count(*) as n from ai_rows group by 1, 2, 3, 4, 5) a), '[]'::jsonb),
    'practice', jsonb_build_object(
      'done_28d', (select count(*) from public.practice_answers where student_id = p_student and done and updated_at >= since_28),
      'tests_28d', (select count(*) from public.practice_attempts where student_id = p_student and submitted_at >= since_28),
      'interviews_28d', (select count(*) from public.interview_sessions where student_id = p_student and created_at >= since_28),
      -- Tests retaken after earlier AI feedback on the same test: evidence of revision.
      'repeats_after_feedback_28d', (
        select count(*) from public.practice_attempts pa
        where pa.student_id = p_student and pa.submitted_at >= since_28
          and exists (select 1 from public.ai_evaluations e join public.practice_attempts prev on prev.id = e.subject_id
                      where e.subject_type = 'practice_attempt' and prev.student_id = p_student
                        and prev.bank_slug = pa.bank_slug and e.created_at < pa.submitted_at))
    ),
    'library_28d', (select count(*) from public.content_progress where student_id = p_student and completed_at >= since_28),
    'attendance', jsonb_build_object(
      'present', (select count(*) from public.session_attendance where student_id = p_student and status = 'present'),
      'absent', (select count(*) from public.session_attendance where student_id = p_student and status = 'absent')),
    'active_days_28', (select count(distinct day) from activity),
    'active_days_7', (select count(distinct day) from activity where day >= (since_7 at time zone 'Asia/Kolkata')::date)
  ) into result;
  return result;
end;
$$;

revoke execute on function public.readiness_signals(uuid) from public, anon;
grant execute on function public.readiness_signals(uuid) to authenticated;

-- ===========================================================================
-- 0021_diagnostic_roadmap.sql
-- ===========================================================================
-- SSB Academy — T105: onboarding preferences + diagnostic baseline (PRD §9.1–9.3,
-- FR-ONB-01/02, FR-PLAN-01). Run once in the Supabase SQL Editor, AFTER 0020.
--
--  * Onboarding moves from the browser into the account: entry scheme, target
--    SSB date, self-reported preparation stage, preferred language and daily
--    study time — editable any time (PRD §9.2).
--  * A short, low-anxiety diagnostic: 8 multiple-choice questions (SSB
--    knowledge and reasoning, scored here) and 4 short written answers
--    (communication, situational reasoning, self-awareness — AI feedback,
--    rubric 'diagnostic' v1). The FIRST attempt is the baseline and can never
--    change; later attempts are re-assessments stored separately, so before
--    and after can be compared honestly.
--  * The roadmap is computed by the app from these and the readiness profile
--    (lib/server/roadmap), so it recalculates whenever new evidence arrives.

alter table public.student_profiles
  add column entry_scheme text,
  add column target_ssb_date date,
  add column preferred_language text not null default 'en',
  add column daily_study_minutes integer,
  add column onboarded_at timestamptz,
  add constraint student_profiles_scheme check (entry_scheme is null or entry_scheme in ('nda', 'cds', 'afcat', 'tes', 'tgc', 'ssc', 'ncc', 'other')),
  add constraint student_profiles_stage check (preparation_stage is null or preparation_stage in ('just_starting', 'in_progress', 'final_stretch')),
  add constraint student_profiles_language check (preferred_language in ('en', 'hi')),
  add constraint student_profiles_minutes check (daily_study_minutes is null or daily_study_minutes between 10 and 600),
  add constraint student_profiles_goals check (goals is null or char_length(goals) <= 500);

-- Mentors and academy admins may read a student's preferences (to guide them).
create policy "student_profiles_mentor_read" on public.student_profiles for select using (public.is_my_mentee(user_id));
create policy "student_profiles_admin_read" on public.student_profiles for select using (
  exists (select 1 from public.profiles p where p.id = user_id and p.academy_id is not null and p.academy_id = public.current_admin_academy_id())
);

create function public.save_student_preferences(
  p_entry_scheme text, p_target_date date, p_stage text, p_language text, p_daily_minutes integer, p_goals text
)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  if auth.uid() is null or public.current_user_role() <> 'student' then
    raise exception 'only a student has preparation preferences' using errcode = '42501';
  end if;
  if p_target_date is not null and (p_target_date < current_date or p_target_date > current_date + 730) then
    raise exception 'target date must be within the next two years' using errcode = '23514';
  end if;
  insert into public.student_profiles (user_id) values (auth.uid()) on conflict (user_id) do nothing;
  update public.student_profiles
  set entry_scheme = p_entry_scheme, target_ssb_date = p_target_date, preparation_stage = p_stage,
      preferred_language = coalesce(p_language, 'en'), daily_study_minutes = p_daily_minutes,
      goals = nullif(btrim(coalesce(p_goals, '')), ''),
      onboarded_at = coalesce(onboarded_at, now()), updated_at = now()
  where user_id = auth.uid();
end;
$$;

revoke execute on function public.save_student_preferences(text, date, text, text, integer, text) from public, anon;
grant execute on function public.save_student_preferences(text, date, text, text, integer, text) to authenticated;

